(function(){'use strict';
const store=window.N1078_ESSAYS, catalog=window.N27_CATALOG;
if(!store?.items||!Array.isArray(catalog?.items))return;
const additions={"2025-econ-1":{"parts":[{"heading":"Ⅰ. 조건, 좌표계 및 분석의 전제","text":"이 문제의 핵심은 소비-여가 평면의 최적 선택을 다섯 가지 예산제약 아래에서 각각 다시 풀어 비교하는 것이다. 주당 총시간 T=100, 근로시간 h=100−L이며 소비 단위와 임금 단위를 모두 만원으로 통일한다. 기본 임금률 w=1일 때 C=h=100−L, 따라서 예산선의 세로축 절편은 100, 가로축 절편은 100이다. 모든 경우의 최적화는 U(C,L)=CL에 원래의 예산제약을 대입한 다음 0≤h≤100의 허용 구간에서 극댓값을 판정한다. 미분으로 나온 값이 경계의 후보보다 실제로 큰지 확인해야 한다. 자주 나오는 실수는 여가 L과 근로 h를 같은 방향으로 증가시키거나, 초과근로를 모든 시간에 소급 적용하는 것이다."},{"heading":"Ⅱ. 물음 1 — 기준 예산과 내점해 검산","text":"기본 예산의 소비는 C=100−L이므로 U=(100−L)L=100L−L²이다. 일계조건 dU/dL=100−2L=0에서 L*=50, h*=50, C*=50, U*=2,500을 얻는다. 이계조건 d²U/dL²=−2<0이므로 이는 허용 구간에서 극대점이다. 소비의 한계효용 MU_C=L, 여가의 한계효용 MU_L=C이므로 MRS_{L,C}=C/L=1, 세후 여가의 기회비용 w=1과도 일치한다. 그래프에서는 (L,C)=(50,50)을 지나는 무차별곡선이 C=100−L에 접하며, 원점 쪽의 무차별곡선보다 높은 효용을 갖는다. 반드시 '50시간'이 여가와 노동 모두에 해당한다는 점을 분명히 적는다."},{"heading":"Ⅲ. 물음 2 — 초과근로의 꺾인 예산선","text":"50시간까지는 C=h이지만 50시간을 초과한 부분에만 2만원이 적용되므로 C=50+2(h−50)=2h−50이다. h=100−L을 대입하면 여가가 50 이상인 구간에서는 C=100−L, 여가가 50 미만인 초과근로 구간에서는 C=150−2L이다. 두 구간은 (L,C)=(50,50)에서 만나므로 예산선에 단절은 없지만 기울기가 −1에서 −2로 바뀐다. 초과근로 구간의 효용은 U=(150−2L)L=150L−2L²이고 일계조건 150−4L=0에서 L=37.5, h=62.5, C=75, U=2,812.5이다. 후보는 L<50이라는 구간 조건을 충족한다. 기준 구간의 최대 효용은 접점 L=50에서 2,500이므로 초과근로 후보가 전역 최적이다. 초과근로 12.5시간과 총 근로 62.5시간을 혼동하지 않도록 구분한다."},{"heading":"Ⅳ. 물음 3 — 전체 임금 1.2만원 인상과의 비교","text":"임금률이 전체 근로시간에 대해 1.2만원이면 예산은 C=1.2(100−L)이며 꺾임이 없다. 효용 U=1.2(100L−L²), 일계조건 120−2.4L=0으로 L*=50, h*=50, C*=60, U*=3,000을 얻는다. 동일한 코브·더글러스 선호에서는 비근로소득이 0이고 전 시간에 임금률만 일정 비율 상승할 때 최적 노동시간이 그대로인 점을 설명할 수 있다. 반면 물음 2의 초과근로 할증은 기준 50시간 이후 구간의 상대가격만 바꾸어 더 많은 근로를 유인한다. 숫자 비교는 '기준: h=50, C=50, U=2500 / 할증: h=62.5, C=75, U=2812.5 / 일률 인상: h=50, C=60, U=3000'으로 정리한다. 효용 수준이 더 높은 것은 일률 인상안이지만, 두 제도의 노동시간 유인은 다르다."},{"heading":"Ⅴ. 물음 4 — 비근로소득 40만원","text":"기준 임금률 1만원에서 비근로소득 V=40만원이 추가되면 소비는 C=40+h=140−L이다. 그래프에서 직선의 기울기 −1은 유지되고 여가 100에서 소비절편이 40으로 올라가 평행이동한다. 최적 효용은 U=(140−L)L=140L−L²이므로 L*=70, h*=30, C*=70, U*=4,900이다. 여가가 정상재라는 점을 나타내듯 비근로소득이 없는 경우보다 여가가 20시간 늘고 노동은 20시간 줄어든다. 비근로소득은 임금 인상과 달리 여가의 상대가격을 직접 변화시키지 않으므로, 기본 모형의 비교에서 대체효과가 아니라 소득효과에 주목한다. 소비가 늘면서 노동이 줄어든다는 사실만으로 효용의 악화를 추론하지 않아야 한다."},{"heading":"Ⅵ. 물음 5 — 유보임금의 도출","text":"유보임금은 현재 비근로 상태에서 여가 한 시간을 포기하도록 유도하는 최소한의 임금률이다. 노동을 전혀 하지 않으면 L=T=100, C=V이므로 이 점에서 여가의 한계가치가 얼마인지 계산한다. U=CL의 한계효용은 MU_L=C, MU_C=L이고 소비로 표시한 여가의 한계대체율은 MU_L/MU_C=C/L=V/100이다. 따라서 유보임금 w_R=V/100(만원/시간)이다. w_R=1이 되려면 비근로소득 V=100만원이어야 한다. 이 값은 노동을 하지 않는 근로자에게 부여되는 주간 비근로소득이지 기존 임금에서 추가로 지급해야 하는 금액이 아니다. 최적조건을 경계점 h=0에서 적용한다는 점이 핵심이다."},{"heading":"Ⅶ. 그래프 표기와 검산 결론","text":"그래프는 여가를 수평축, 소비를 수직축에 둔다. 기본점(50,50), 할증점(37.5,75), 일률 인상점(50,60), 비근로소득점(70,70)을 각각 표시하고, 할증 예산의 꺾임 (50,50)을 따로 표시한다. y축과 x축 절편, 기울기 및 허용구간을 쓰면 구체적 함수와 도형의 대응이 분명해진다. 예산선에 접선 조건을 적용해도 모든 경우에 내점해가 존재한다고 미리 가정해서는 안 된다. 본 문제는 제시된 함수에서 위의 값들이 각 구간의 조건을 충족하므로 계산으로 확인할 수 있다. 답안에는 최적 여가·근로·소비·효용을 네 행으로 묶어 대조하는 것이 검산에 유리하다."},{"heading":"Ⅷ. 최적해의 조건과 경계 비교","text":"효용함수 U=CL은 소비 C와 여가 L이 모두 양일 때 효용이 증가하고 각 선택의 한계효용이 양수다. 고정된 예산선에서는 여가 한 시간을 늘릴 때 소비할 수 있는 액수가 감소하므로, 두 효과가 균형을 이루는 지점에서 내부해를 얻는다. 기본·일률 인상·비근로소득 예산에서는 목적함수를 L의 이차식으로 바꾸면 음의 이계미분을 얻는다. 초과근로 예산은 꺾인 선이므로 구간을 구분해야 한다. 구간에서 구한 최적해가 실제 그 구간의 정의역 안에 들어가는지를 확인하고 꺾임점에서의 효용과 직접 비교한다. 이 절차가 빠지면 잘못된 구간의 가짜 미분해를 최적점으로 채택할 수 있다."},{"heading":"Ⅸ. 노동공급과 후생 변화의 분석","text":"기본상황과 비교하면 초과근로 할증정책은 고임금 구간으로 추가 근로를 유인하여 노동시간 12.5시간 증가, 소비 25만원 증가, 여가 12.5시간 감소로 나타난다. 반면 전체 임금률 20% 인상은 최적 근로시간을 바꾸지 않고 소비를 10만원 늘린다. 비근로소득 40만원의 도입은 소득효과로 여가를 늘리고 노동을 20시간 줄이면서 소비를 20만원 늘린다. 주어진 선호의 효용은 각각 2500, 2812.5, 3000, 4900으로 비교할 수 있다. 그러나 초과근로와 일률 임금인상은 기업 비용이나 정책 시행가능성이 서로 다르므로 이 효용 숫자만으로 사회적 순편익을 평가할 수는 없다. 답안의 결론은 개별 근로자의 최적선택 비교에 한정한다."},{"heading":"Ⅹ. 단위·기호의 통일","text":"수식에서 소비 C는 만원, 임금 w는 만원/시간, 노동 h와 여가 L은 시간으로 표시했다. 따라서 예를 들어 근로 62.5시간일 때 소비 C=75는 75만원을 의미한다. 원문에서 총시간 100은 주당 사용 가능 여가시간의 최대값이며, h+L=100이라는 시간제약과 동일한 말이다. 비근로소득 40과 유보임금 도출을 위한 비근로소득 100은 각각 별개의 물음에서 나온 값이므로 혼동하면 안 된다. 모든 선택의 효용은 동일한 U=CL 함수값이므로 문제 안에서는 비교 가능하되, 이를 금전적인 후생 변화나 전체 노동시장효과로 해석하지 않는다고 명시한다."},{"heading":"Ⅷ. 최적해의 조건과 경계 비교","text":"효용함수 U=CL은 소비 C와 여가 L이 모두 양일 때 효용이 증가하고 각 선택의 한계효용이 양수다. 고정된 예산선에서는 여가 한 시간을 늘릴 때 소비할 수 있는 액수가 감소하므로, 두 효과가 균형을 이루는 지점에서 내부해를 얻는다. 기본·일률 인상·비근로소득 예산에서는 목적함수를 L의 이차식으로 바꾸면 음의 이계미분을 얻는다. 초과근로 예산은 꺾인 선이므로 구간을 구분해야 한다. 구간에서 구한 최적해가 실제 그 구간의 정의역 안에 들어가는지를 확인하고 꺾임점에서의 효용과 직접 비교한다. 이 절차가 빠지면 잘못된 구간의 가짜 미분해를 최적점으로 채택할 수 있다."},{"heading":"Ⅸ. 노동공급과 후생 변화의 분석","text":"기본상황과 비교하면 초과근로 할증정책은 고임금 구간으로 추가 근로를 유인하여 노동시간 12.5시간 증가, 소비 25만원 증가, 여가 12.5시간 감소로 나타난다. 반면 전체 임금률 20% 인상은 최적 근로시간을 바꾸지 않고 소비를 10만원 늘린다. 비근로소득 40만원의 도입은 소득효과로 여가를 늘리고 노동을 20시간 줄이면서 소비를 20만원 늘린다. 주어진 선호의 효용은 각각 2500, 2812.5, 3000, 4900으로 비교할 수 있다. 그러나 초과근로와 일률 임금인상은 기업 비용이나 정책 시행가능성이 서로 다르므로 이 효용 숫자만으로 사회적 순편익을 평가할 수는 없다. 답안의 결론은 개별 근로자의 최적선택 비교에 한정한다."},{"heading":"Ⅹ. 단위·기호의 통일","text":"수식에서 소비 C는 만원, 임금 w는 만원/시간, 노동 h와 여가 L은 시간으로 표시했다. 따라서 예를 들어 근로 62.5시간일 때 소비 C=75는 75만원을 의미한다. 원문에서 총시간 100은 주당 사용 가능 여가시간의 최대값이며, h+L=100이라는 시간제약과 동일한 말이다. 비근로소득 40과 유보임금 도출을 위한 비근로소득 100은 각각 별개의 물음에서 나온 값이므로 혼동하면 안 된다. 모든 선택의 효용은 동일한 U=CL 함수값이므로 문제 안에서는 비교 가능하되, 이를 금전적인 후생 변화나 전체 노동시장효과로 해석하지 않는다고 명시한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-econ-1":{"parts":[{"heading":"Ⅰ. 물음별 요구와 단위 설정","text":"원문은 20% 급여세가 부과되는 초기 상태와 세율 40%·현금보조 36,000원이 결합한 새로운 정책을 비교하도록 요구한다. 소비 단위를 만원으로 통일하면 시간당 세전임금 w=1, 세후임금은 각각 0.8과 0.6, 현금보조는 3.6이다. 총시간 24에서 여가 L과 노동 h=24−L만 선택 가능하다. 정책의 두 요소가 동시에 바뀌므로 대체효과와 소득효과를 하나의 세율 변화만으로 단정하지 않는 것이 중요하다. 효용 U=3CL은 미분에 편리하지만 함수 앞의 상수 3은 최적선택 자체를 바꾸지 않는다. 그래프에서는 여가축·소비축의 단위와 새 보조금에 따른 비근로 점도 정확히 적는다."},{"heading":"Ⅱ. 물음 1 — 예산선의 절편·회전 및 교차","text":"정책 전 소비는 C=0.8h=0.8(24−L)=19.2−0.8L이다. 여가가 0일 때 소비 19.2, 24일 때 0이므로 (L,C)=(0,19.2)와 (24,0)을 연결한다. 정책 후 소비는 C=3.6+0.6(24−L)=18−0.6L이고 두 절편은 (0,18), (24,3.6)이다. 즉 노동을 전혀 하지 않아도 비근로소득 때문에 3.6만원을 소비할 수 있지만, 여가 한 시간의 기회비용은 0.8만원에서 0.6만원으로 낮아진다. 두 예산선의 교차는 19.2−0.8L=18−0.6L에서 L=6, C=14.4이다. 6시간보다 여가가 적은 사람은 기존 예산선의 소비 가능액이 높고, 6시간보다 여가가 큰 사람은 새 정책의 소비 가능액이 높다는 점을 그래프로 표현하면 정책의 이질적 영향도 드러난다."},{"heading":"Ⅲ. 물음 2 — 최적점 도출과 극대성 검산","text":"정책 전 U(L)=3L(19.2−0.8L)=57.6L−2.4L², 일계조건 57.6−4.8L=0에서 L=12이다. 따라서 h=12, C=9.6, U=3×9.6×12=345.6이며 이계미분 −4.8은 음수다. 정책 후 U(L)=3L(18−0.6L)=54L−1.8L²이고 일계조건 54−3.6L=0에서 L=15를 얻는다. 따라서 h=9, C=9, U=405이며 이계미분 −3.6 역시 음수다. 두 해 모두 0≤L≤24를 만족한다. 그래프에서 각각의 최적점은 새로운 예산선과 무차별곡선이 접하는 위치이며, MRS=C/L이 각 시점 세후임금과 일치한다: 정책 전 9.6/12=0.8, 정책 후 9/15=0.6."},{"heading":"Ⅳ. 물음 3 — 대체효과와 소득효과 분리","text":"세후임금이 낮아지면 여가를 한 시간 포기해 얻는 소비가 줄어드므로 여가의 상대가격이 낮아지고, 보상된 대체효과는 여가 증가·노동 감소 방향이다. 한편 임금 감소의 순수 소득효과는 여가가 정상재라면 여가 감소 방향이고, 별도의 현금보조는 여가 증가 방향이다. 이 문제에서 실제 최적 여가는 12→15로 3시간 증가하고 노동은 12→9로 3시간 감소한다. 따라서 임금 변화와 보조금 효과를 통합한 순효과는 노동공급 감소다. 대체효과와 소득효과 각각에 정확한 수치를 부여하려면 보상 기준을 명시해야 하므로, 단순히 3시간을 임의 비율로 쪼개는 것은 부적절하다."},{"heading":"Ⅴ. 힉스 보상분해의 수치 예시","text":"힉스의 보상변화를 예로 들면 원래 효용 U₀=345.6을 유지한 채 새 세후임금 0.6에 접하는 소비-여가 조합을 구할 수 있다. 내점 접선조건 C/L=0.6에서 C=0.6L이고, 효용조건 3CL=345.6에 대입하면 1.8L²=345.6이다. 따라서 Lᴴ=√192≈13.856, Cᴴ≈8.314이다. 보상된 대체효과는 여가 12→13.856, 약 1.856시간 증가이며, 나머지 새 정책에 대한 소득효과는 여가 13.856→15, 약 1.144시간 증가로 표현된다. 다만 이 두 번째 단계는 세율 인상만의 소득효과가 아니라 현금보조를 포함한 최종 예산선까지의 이동이다. 슬러츠키 보상분해를 택하면 기준이 달라 수치도 달라질 수 있음을 명시한다."},{"heading":"Ⅵ. 효용·노동공급 비교와 결론","text":"정책 전후 소비량 자체는 9.6→9로 소폭 감소하지만 여가가 12→15로 증가하여 효용은 345.6→405로 59.4(약 17.2%) 증가한다. 여기에서 효용 수치는 원문의 지수·상수 선택에 따른 지표이며 개인 간 후생의 객관적 화폐액으로 해석해서는 안 된다. 새 정책은 전혀 일하지 않는 상태에서 보조금을 보장하지만 세후임금의 기회비용은 줄이므로 여가 선택을 상대적으로 유리하게 만든다. 24시간 전부 일하거나 전부 여가로 쓰는 경계선보다 구한 내점이 높은 효용을 갖는 것도 확인된다. 마지막 문장은 '이 사례의 효용함수와 수치 아래 노동 3시간 감소·효용 59.4 증가'로 제한하고 모든 근로자에게 일반화하지 않는 것이 적절하다."},{"heading":"Ⅶ. 최초소득 기준의 슬러츠키 보상과 구분","text":"대체효과의 크기가 보상방식에 따라 달라지는 점을 설명할 수 있다. 슬러츠키 보상은 가격이 바뀐 뒤에도 최초 선택 (L,C)=(12,9.6)을 구입할 수 있도록 소득을 조정하는 방식이다. 새 임금의 예산선 기울기 −0.6으로 이 점을 지나는 가상 예산선은 C=16.8−0.6L이다. 이 예산선 위의 효용극대화는 L=14, C=8.4이므로 슬러츠키 대체효과는 여가 12→14, 즉 2시간 증가이다. 실제 정책 후 여가 15와 비교하면 슬러츠키 소득효과는 추가 1시간 증가다. 앞서 힉스 보상에서 계산한 1.856과 1.144라는 분해와 합계는 같지만 구성은 다르다. 이 차이를 모순으로 보지 말고 보상 기준의 차이로 설명한다. 단, 슬러츠키의 보상소득은 정책 자체의 실제 현금보조 지급액과 동일한 개념이 아니다."},{"heading":"Ⅷ. 상대가격 변화와 기준점의 해석","text":"새 정책 예산선은 모든 여가수준에서 초기 예산선보다 위에 있는 것은 아니다. 두 선은 L=6에서 교차한다. 따라서 예산기회의 변화가 노동시간이 많은 사람과 여가가 많은 사람에게 동일하게 유리하다고 말할 수 없다. 효용을 극대화하는 해당 근로자의 초기 여가가 12인 점이 중요하다. 초기 선택 (12,9.6)에서 새 정책으로 얻을 수 있는 소비액은 18−0.6×12=10.8이다. 즉 최초 최적점은 새 예산집합 안에서도 허용되므로 새 정책 최적 효용은 최소한 345.6 이상이어야 한다. 실제로 405가 나와 이 논리와 일치한다. 이런 지배관계 검산은 수치 계산 과정에서 단위나 부호가 뒤바뀌었는지를 찾아내는 데 유용하다."},{"heading":"Ⅸ. 그래프 작성 순서와 모서리해 확인","text":"시험장 답안에서는 첫째, 횡축 여가 0~24와 종축 소비 0~19.2를 표시한다. 둘째, 정책 전 (0,19.2)와 (24,0), 정책 후 (0,18)와 (24,3.6)을 잇는다. 셋째, 두 예산선의 교차점 (6,14.4)을 표시한다. 넷째, 전·후 최적점 (12,9.6), (15,9)에 해당하는 무차별곡선을 각각 접하게 그린다. 다섯째, 효용이 345.6→405로 증가했다는 문장을 그래프의 곡선 수준과 연결한다. 여가 0 또는 24에서는 원문의 U=3CL에 따라 C=0이거나 L=0이 되어 효용이 0이므로, 구한 내점이 경계보다 우월하다는 점을 확인할 수 있다."},{"heading":"Ⅹ. 노동공급정책 평가의 범위","text":"정책 시행 전후의 노동시간 변화는 실제 시장의 집단별 노동공급 탄력성을 추정한 결과가 아니라 주어진 한 사람의 이론적 선택 계산이다. 현금보조금의 재원 마련에 추가적인 왜곡이나 재정비용이 있는지, 근로자가 일할 수 있는 시간이 24시간으로 제한되는 현실적 제약, 수혜자 유형별 차이 등은 원문에 포함되지 않았다. 따라서 사회후생 전체나 정부의 세수효과에 관한 결론으로 곧장 확장해서는 안 된다. 출제 문제의 범위에서는 예산선의 변화, 내점해, 노동공급 방향, 효용 숫자를 정확히 제시하는 것으로 충분하다."},{"heading":"Ⅶ. 최초소득 기준의 슬러츠키 보상과 구분","text":"대체효과의 크기가 보상방식에 따라 달라지는 점을 설명할 수 있다. 슬러츠키 보상은 가격이 바뀐 뒤에도 최초 선택 (L,C)=(12,9.6)을 구입할 수 있도록 소득을 조정하는 방식이다. 새 임금의 예산선 기울기 −0.6으로 이 점을 지나는 가상 예산선은 C=16.8−0.6L이다. 이 예산선 위의 효용극대화는 L=14, C=8.4이므로 슬러츠키 대체효과는 여가 12→14, 즉 2시간 증가이다. 실제 정책 후 여가 15와 비교하면 슬러츠키 소득효과는 추가 1시간 증가다. 앞서 힉스 보상에서 계산한 1.856과 1.144라는 분해와 합계는 같지만 구성은 다르다. 이 차이를 모순으로 보지 말고 보상 기준의 차이로 설명한다. 단, 슬러츠키의 보상소득은 정책 자체의 실제 현금보조 지급액과 동일한 개념이 아니다."},{"heading":"Ⅷ. 상대가격 변화와 기준점의 해석","text":"새 정책 예산선은 모든 여가수준에서 초기 예산선보다 위에 있는 것은 아니다. 두 선은 L=6에서 교차한다. 따라서 예산기회의 변화가 노동시간이 많은 사람과 여가가 많은 사람에게 동일하게 유리하다고 말할 수 없다. 효용을 극대화하는 해당 근로자의 초기 여가가 12인 점이 중요하다. 초기 선택 (12,9.6)에서 새 정책으로 얻을 수 있는 소비액은 18−0.6×12=10.8이다. 즉 최초 최적점은 새 예산집합 안에서도 허용되므로 새 정책 최적 효용은 최소한 345.6 이상이어야 한다. 실제로 405가 나와 이 논리와 일치한다. 이런 지배관계 검산은 수치 계산 과정에서 단위나 부호가 뒤바뀌었는지를 찾아내는 데 유용하다."},{"heading":"Ⅸ. 그래프 작성 순서와 모서리해 확인","text":"시험장 답안에서는 첫째, 횡축 여가 0~24와 종축 소비 0~19.2를 표시한다. 둘째, 정책 전 (0,19.2)와 (24,0), 정책 후 (0,18)와 (24,3.6)을 잇는다. 셋째, 두 예산선의 교차점 (6,14.4)을 표시한다. 넷째, 전·후 최적점 (12,9.6), (15,9)에 해당하는 무차별곡선을 각각 접하게 그린다. 다섯째, 효용이 345.6→405로 증가했다는 문장을 그래프의 곡선 수준과 연결한다. 여가 0 또는 24에서는 원문의 U=3CL에 따라 C=0이거나 L=0이 되어 효용이 0이므로, 구한 내점이 경계보다 우월하다는 점을 확인할 수 있다."},{"heading":"Ⅹ. 노동공급정책 평가의 범위","text":"정책 시행 전후의 노동시간 변화는 실제 시장의 집단별 노동공급 탄력성을 추정한 결과가 아니라 주어진 한 사람의 이론적 선택 계산이다. 현금보조금의 재원 마련에 추가적인 왜곡이나 재정비용이 있는지, 근로자가 일할 수 있는 시간이 24시간으로 제한되는 현실적 제약, 수혜자 유형별 차이 등은 원문에 포함되지 않았다. 따라서 사회후생 전체나 정부의 세수효과에 관한 결론으로 곧장 확장해서는 안 된다. 출제 문제의 범위에서는 예산선의 변화, 내점해, 노동공급 방향, 효용 숫자를 정확히 제시하는 것으로 충분하다."},{"heading":"Ⅺ. 최종 요약표를 통한 오류 방지","text":"정책 전후의 결과는 각 축의 단위가 같아야 비교할 수 있다. 정책 전은 세후임금 0.8, 보조금 0, 여가 12, 노동 12, 소비 9.6, 효용 345.6이다. 정책 후는 세후임금 0.6, 보조금 3.6, 여가 15, 노동 9, 소비 9, 효용 405이다. 두 상태의 소비 차이는 −0.6만원, 노동 차이는 −3시간이다. 보조금의 현금액만을 보고 소비가 반드시 늘어난다고 추론하지 말고, 근로시간 선택의 동시 변화를 반영해야 한다. 합계 근로·여가 24시간이라는 시간제약도 두 경우 모두 충족한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-hr-1":{"parts":[{"heading":"Ⅰ. 국제인적자원관리의 선택문제","text":"국제인적자원관리는 본국과 진출국을 가로지르는 인력의 확보·배치·육성·평가·보상·이동을 통합적으로 다룬다. 핵심 긴장은 본사 통제와 글로벌 통합을 얼마나 유지할 것인지, 그리고 현지 노동시장·문화·제도·고객환경에 얼마나 적응할 것인지의 균형이다. 원문은 접근방식 네 가지의 장단점을 20점으로, 해외주재원의 역할과 선발·훈련·보상·유지·귀임 관리를 30점으로 요구한다. 따라서 첫 물음에서 EPRG 분류와 인력충원 정책의 차이를 비교하고 둘째 물음에서 해외 파견의 전 과정을 연결하여 설명한다. 국제기업의 규모나 국가 수만으로 특정 접근방식이 무조건 우월하다고 판단하지 않는 것이 중요하다."},{"heading":"Ⅱ. EPRG 네 접근방식의 구분과 비교","text":"본국중심(ethnocentric)은 핵심 직책에 본국 인력을 배치하고 본사의 원칙·기술·문화가 해외 자회사에도 적용되도록 한다. 초기 해외진출, 기술·품질 관리의 통일에 유리하나 현지 관리자 승진 경로와 대응력이 제한될 수 있다. 현지중심(polycentric)은 현지 자회사에 현지 경영자를 맡겨 현지 규범과 시장에 적응하지만, 본사와 자회사 사이의 지식·인사 이동이 단절되고 국가별 운영이 분산될 위험이 있다. 권역중심(regiocentric)은 아시아·유럽처럼 권역을 단위로 인력을 순환·개발하여 해당 권역의 통합을 강화하는 대신 권역 간 장벽이 생길 수 있다. 세계중심(geocentric)은 국적과 관계없이 최적 인재를 활용하고 글로벌 경력체계를 구축하지만 이민·취업 허가, 세제, 노동법, 이동비용, 보상 형평성의 조정 부담이 크다. EPRG는 국제 인사·의사결정의 성향을 보여주는 틀이며 일률적 인력 배치만으로 모든 조직전략을 설명하지는 않는다."},{"heading":"Ⅲ. 접근방식과 조직·인사제도의 적합성","text":"본국중심에서는 본사의 본국 관리자 중심 경력관리와 본국식 성과평가가 확대되기 쉬우며 기술이전 및 통제 목적의 해외주재원 활용이 상대적으로 많다. 현지중심에서는 현지 노동시장의 보상수준과 관행을 존중하고 현지 관리자 개발을 중시하지만, 본사의 국제적 승계계획과 연결하는 장치가 필요하다. 권역중심에서는 유사한 시장·문화·제도 환경을 전제로 권역별 인력풀과 이동경로를 마련하되 권역 내 다양성도 고려해야 한다. 세계중심에서는 글로벌 역량모델·직무등급·인재 데이터가 중요하고 본사와 해외법인 쌍방향 이동을 지원해야 한다. 평가축은 현지적응, 본사통제, 국경 간 지식이전, 관리비용, 관리자의 성장기회 다섯 가지로 잡으면 비교가 명료하다. 각 방식의 장점을 실제 사업전략과 연결하지 않고 단순 암기식으로만 열거하면 물음의 요구를 충분히 충족하지 못한다."},{"heading":"Ⅳ. 해외주재원의 역할과 선발","text":"해외주재원은 해외법인 설립과 운영에서 본사의 전략을 구현하고, 기술·관리 노하우를 이전하며, 본사와 현지조직의 상호 신뢰를 잇는 연결자 역할을 수행한다. 장기적으로는 국제적 경력을 갖춘 리더를 육성하고 현지에서 얻은 지식을 귀임 후 본사에 환류시키는 역할도 있다. 선발할 때 직무기술·성과뿐 아니라 문화적 감수성, 불확실성 대처력, 의사소통, 협력 태도, 배우자·가족의 적응 가능성을 검토한다. 현지법과 조직의 윤리기준을 준수할 역량이 없으면 기술적 성과가 높아도 파견 실패 위험이 커질 수 있다. 선발 과정에서 직무목표와 파견 종료 후 경력경로를 사전에 설명하여 지원자의 현실적 기대를 형성하는 것이 중요하다."},{"heading":"Ⅴ. 교육훈련과 보상의 설계","text":"출국 전 교육은 언어와 생활문화에 한정하지 않고 현지 노동·세무·출입국 제도, 고객 및 협상 관행, 직무 수행, 안전·보건 리스크, 윤리적 의사결정을 포함해야 한다. 현지 도착 후에는 멘토·현지 관리자와 함께 실제 업무 갈등 및 보고체계를 점검하는 현장 적응 훈련이 필요하다. 보상은 본국·현지 기준 중 무엇을 채택하는지 정해 기본급, 환율·물가 차이, 주거·자녀교육, 세금 조정, 위험수당, 의료·사회보장 비용을 구조적으로 검토한다. 예를 들어 동일 직급의 본국 근로자와 해외근로자의 순수령액 차이가 커지면 보상 공정성 논란이 생길 수 있다. 생활비 보전과 성과보상을 구분하고 과도한 수당이 귀임 후 보상 갈등으로 이어지지 않도록 한다."},{"heading":"Ⅵ. 유지관리·성과평가·귀임","text":"파견 기간 동안 본사와의 연락 두절은 경력 단절과 고립을 초래할 수 있으므로 정기적인 피드백·원격 경력상담·멘토링과 가족 지원이 필요하다. 현지 관리자와 본사 관리자 중 누가 평가할지, 단기 재무성과와 장기적인 역량이전·현지인 육성을 어떻게 균형 있게 측정할지 사전에 정해야 한다. 귀임 시에는 해당 직원이 해외 경험을 적용할 직무를 마련하고, 현지에서 습득한 네트워크와 업무지식을 조직 차원의 자산으로 이전해야 한다. 역문화충격, 소득 감소, 가족 재적응을 방치하면 우수 인력의 조기 이탈과 해외투자 지식의 손실로 이어질 수 있다. 파견 비용이 크므로 파견의 성과는 현지 매출뿐 아니라 현지 인재 육성, 지식 이전, 후속 승계인력 확보 등으로 함께 평가한다."},{"heading":"Ⅶ. 결론과 실전 점검","text":"EPRG 접근방식은 본국 통제에서 세계적 인재 최적배치에 이르는 네 선택을 설명하지만, 실제 조직에서는 사업부·국가·직무별로 혼합 형태가 나타난다. 그러므로 답안에서는 네 유형을 표로 비교한 다음 해외주재원 관리가 어떤 유형을 뒷받침하는지 연결하는 것이 좋다. 해외주재원 관리 역시 선발 한 번으로 완성되지 않고 사전준비-현지적응-성과관리-귀임으로 이어지는 순환과정으로 이해해야 한다. 필수 체크는 네 접근방식 명칭과 각각의 장단점, 주재원 역할, 선발, 훈련, 보상, 유지, 귀임을 빠짐없이 썼는지이다. 구체적 보상체계의 우수성은 기업의 국가별 조건과 제도적 제약을 검토한 뒤 판단해야 한다."},{"heading":"Ⅷ. 국제보상·평가·경력 체계의 연동","text":"인적자원관리 정책을 국제사업전략과 연결하려면 채용방식 외에도 직무등급, 인사평가, 승계계획, 지식공유 구조를 함께 설계해야 한다. 예컨대 세계중심 전략을 선언하면서 실제 승진후보는 본국 직원에게만 열려 있다면 글로벌 역량 활용이라는 원칙과 제도가 충돌한다. 반대로 현지중심을 택했더라도 보안·기술표준·핵심 윤리규정까지 모두 분산할 필요는 없다. 중앙에서 통일할 요소와 현지에 위임할 요소를 구분한 인사 거버넌스가 중요하다. 성과평가도 매출만 보는 대신 현지인력 육성, 본사와 현지 간 지식 이전, 규범준수, 공동 프로젝트 기여 등 파견 목적에 맞춘 지표가 필요하다."},{"heading":"Ⅸ. 해외주재원의 실패원인과 조기경보","text":"해외주재원 실패는 직무적 전문성이 부족해서만 생기는 것이 아니다. 현지 문화에 대한 적응이 어려워 구성원과 갈등이 생기거나, 가족의 생활·교육·의료 환경이 불안정하여 파견을 조기 종료할 수 있다. 평가 권한이 본사와 현지법인 사이에서 충돌하면 부당한 목표가 설정되고 주재원의 의사결정이 지연될 수 있다. 따라서 파견 전에는 지원자·가족 상담과 현실적 직무소개, 파견 초기에는 문화적 멘토·지원창구, 파견 중에는 정기적 역할확인과 위험조기 보고, 종료 전에는 귀임 직무와 성과환류 일정을 확보해야 한다. 주재원의 적응상황을 사생활 감시와 혼동하지 말고 필요한 도움을 제공하는 방향으로 관리해야 한다."},{"heading":"Ⅹ. 귀임과 조직 학습의 연결","text":"귀임은 해외파견의 마지막 행정절차가 아니라 국제 인사개발 투자를 회수하는 단계다. 해외에서 파악한 고객요구, 현지 규제 대응, 생산·영업 노하우 등을 사내 교육·프로젝트와 연결하지 않으면 인력이 이동하더라도 지식은 조직에 남지 않는다. 귀임 직후 주재원의 경험을 활용할 직무를 부여하고 국내 인사평가가 해외성과를 공정하게 인정하도록 제도를 맞춰야 한다. 동시에 현지에서 성장한 관리자의 경력기회를 넓히면 해외법인 조직역량도 유지할 수 있다. 따라서 주재원 제도의 성패는 파견 기간의 성과, 현지 조직의 자립성, 귀임 후 경력·지식 확산을 함께 평가해야 한다. 이를 EPRG 유형에 따른 국제적 인재이동 정책과 연계해 결론을 작성한다."},{"heading":"Ⅷ. 국제보상·평가·경력 체계의 연동","text":"인적자원관리 정책을 국제사업전략과 연결하려면 채용방식 외에도 직무등급, 인사평가, 승계계획, 지식공유 구조를 함께 설계해야 한다. 예컨대 세계중심 전략을 선언하면서 실제 승진후보는 본국 직원에게만 열려 있다면 글로벌 역량 활용이라는 원칙과 제도가 충돌한다. 반대로 현지중심을 택했더라도 보안·기술표준·핵심 윤리규정까지 모두 분산할 필요는 없다. 중앙에서 통일할 요소와 현지에 위임할 요소를 구분한 인사 거버넌스가 중요하다. 성과평가도 매출만 보는 대신 현지인력 육성, 본사와 현지 간 지식 이전, 규범준수, 공동 프로젝트 기여 등 파견 목적에 맞춘 지표가 필요하다."},{"heading":"Ⅸ. 해외주재원의 실패원인과 조기경보","text":"해외주재원 실패는 직무적 전문성이 부족해서만 생기는 것이 아니다. 현지 문화에 대한 적응이 어려워 구성원과 갈등이 생기거나, 가족의 생활·교육·의료 환경이 불안정하여 파견을 조기 종료할 수 있다. 평가 권한이 본사와 현지법인 사이에서 충돌하면 부당한 목표가 설정되고 주재원의 의사결정이 지연될 수 있다. 따라서 파견 전에는 지원자·가족 상담과 현실적 직무소개, 파견 초기에는 문화적 멘토·지원창구, 파견 중에는 정기적 역할확인과 위험조기 보고, 종료 전에는 귀임 직무와 성과환류 일정을 확보해야 한다. 주재원의 적응상황을 사생활 감시와 혼동하지 말고 필요한 도움을 제공하는 방향으로 관리해야 한다."},{"heading":"Ⅹ. 귀임과 조직 학습의 연결","text":"귀임은 해외파견의 마지막 행정절차가 아니라 국제 인사개발 투자를 회수하는 단계다. 해외에서 파악한 고객요구, 현지 규제 대응, 생산·영업 노하우 등을 사내 교육·프로젝트와 연결하지 않으면 인력이 이동하더라도 지식은 조직에 남지 않는다. 귀임 직후 주재원의 경험을 활용할 직무를 부여하고 국내 인사평가가 해외성과를 공정하게 인정하도록 제도를 맞춰야 한다. 동시에 현지에서 성장한 관리자의 경력기회를 넓히면 해외법인 조직역량도 유지할 수 있다. 따라서 주재원 제도의 성패는 파견 기간의 성과, 현지 조직의 자립성, 귀임 후 경력·지식 확산을 함께 평가해야 한다. 이를 EPRG 유형에 따른 국제적 인재이동 정책과 연계해 결론을 작성한다."},{"heading":"Ⅺ. 해외 파견 목적에 따른 성과지표 차별화","text":"국제인적자원관리의 성과를 단기 수익만으로 재단하면 해외주재원이 교육·기술이전·현지인 육성을 소홀히 할 수 있다. 본사의 통제가 목적이라면 공통 프로세스 정착과 내부통제 준수, 시장개척이 목적이라면 현지 파트너 확보와 고객 이해, 경영인 육성이 목적이라면 차세대 리더의 역량 향상 등 파견 목표에 맞는 지표를 선별한다. 이 지표는 출국 전 정해 현지 평가자와 본사가 합의하고, 귀임 후 경력관리에서도 일관되게 적용해야 한다."}],"sources":[{"author":"Sachiko Yamao","year":2024,"title":"EPRG model (Elgar Encyclopedia of Cross-Cultural Management)","url":"https://keio.elsevierpure.com/en/publications/eprg-model/"}],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-org-1":{"parts":[{"heading":"Ⅰ. 모형의 의의와 물음 구조","text":"조직수명주기는 규모 증가와 성숙에 따라 구조와 관리과제·효과성 기준이 달라질 수 있음을 보여준다. 다만 조직의 성장은 단선적·필연적 법칙이 아니며 단계가 중첩하거나 다시 전환될 수 있다. 제1물음은 퀸과 카메론의 성장단계를 설명하고, 제2물음은 단계별 조직특성 다섯 가지를 명시적으로 비교하며, 제3물음은 위첼·존슨의 쇠퇴단계를 체계적으로 제시하도록 요구한다. 성장모형과 쇠퇴모형은 서로 다른 연구이므로 하나의 단계표에 섞어 적지 않는 것이 중요하다."},{"heading":"Ⅱ. 퀸·카메론 수명주기 4단계","text":"기업가 단계(entrepreneurial)는 혁신적 아이디어·자원 확보·생존과 시장의 틈새 발견이 핵심 과제다. 창업자 의사결정과 비공식 조정이 강해 속도는 빠르지만 리더의 부담이 집중되기 쉽다. 집단성 단계(collectivity)에서는 사명과 공동 정체성, 구성원 몰입·협업을 바탕으로 성장하며 비공식적 소통과 강한 리더십이 여전히 중요하다. 공식화·통제 단계(formalization and control)는 업무 표준화, 직무와 책임의 명확화, 규칙과 관리시스템 도입으로 효율성과 예측가능성을 높인다. 정교화 단계(elaboration of structure)는 분권화와 복잡한 조직구조·통합장치를 병행하며 사업영역 확대와 재활성화를 추구한다. 단계는 조직의 상대적 관리 강조점을 뜻하므로 실제 기업의 모든 부서가 동일한 단계에 있다고 가정해서는 안 된다."},{"heading":"Ⅲ. 단계별 다섯 특성의 정면 비교","text":"첫째, 목표는 초기의 생존·자원 확보에서 집단성 단계의 사명 공유, 공식화의 효율·안정성, 정교화의 적응·혁신으로 달라진다. 둘째, 리더십은 창업자 중심의 직접 통제에서 관계형·동기부여, 절차·성과관리, 분권적 조정으로 이동한다. 셋째, 조직구조는 단순·비공식에서 협업적 구조, 직무분화·규정화, 복합 부문·조정기구로 복잡해진다. 넷째, 의사소통은 직접 대면에서 공동체적 내부교류, 문서·공식 보고, 수평 및 매트릭스형 조정으로 다양화한다. 다섯째, 통제수단은 창업자 판단, 공동규범, 성과지표·규정, 전략적 통합과 팀 기반 학습으로 변한다. 이 다섯 항목을 행으로 하고 4단계를 열로 둔 표를 쓰면 같은 기준으로 비교했다는 점이 분명해진다."},{"heading":"Ⅳ. 성장단계의 문제와 관리 대응","text":"기업가 단계에서는 자금·역량 부족과 리더십 위기가, 집단성 단계에서는 창업자의 직접 통제로 인한 권한위임 문제가 나타날 수 있다. 공식화 단계에서는 규정·절차의 증가가 혁신을 지연시킬 수 있고, 정교화 단계에서는 복잡한 부문을 조정하는 비용과 전략적 초점 상실이 문제일 수 있다. 초기의 속도와 유연성이 성숙 이후에도 동일한 방식으로 효율성을 보장한다고 볼 수 없으며, 반대로 공식화가 필요하다는 이유로 모든 비공식 협력을 제거해서도 안 된다. 성장모형은 각 단계에서 어떤 효과성 지표와 통제장치를 우선할지 판단하는 분석 틀이다."},{"heading":"Ⅴ. 위첼·존슨의 쇠퇴 5단계","text":"첫째, 둔감 또는 맹목 단계(blinded)에서는 변화의 초기 징후를 관찰하지 못한다. 둘째, 무대응 단계(inaction)에서는 문제가 드러나지만 교정 결정을 미루거나 관성적으로 행동한다. 셋째, 잘못된 행동 단계(faulty action)에서는 외부환경과 내부 역량에 맞지 않는 대응으로 비용과 성과의 간극이 확대된다. 넷째, 위기 단계(crisis)에서는 재무·조직적 여력이 크게 줄어 생존을 위한 구조조정과 사업 재편이 시급해진다. 다섯째, 해체 단계(dissolution)에서는 독립적인 조직으로 존속하기 어려운 상태에 이를 수 있다. 이 단계 구분은 위첼과 존슨(1989)의 연구에서 제시된 것으로, 단순히 매출 감소의 정도로만 단계가 결정되는 것은 아니다."},{"heading":"Ⅵ. 조기 경고와 회복전략의 연계","text":"쇠퇴 초기에 필요한 것은 수주잔고, 고객이탈, 현금흐름, 핵심인력 이탈, 품질·안전사고 등 미래 성과를 예고하는 선행지표를 수집해 숨겨진 위험을 인식하는 일이다. 무대응 단계에서는 문제를 공식 의사결정 안건으로 상정하고 대안의 기한과 책임을 정해야 한다. 잘못된 행동 단계에서는 대책이 실패한 이유를 학습하고 사업 포트폴리오·자원배분을 재평가해야 한다. 위기 단계에는 유동성 확보·핵심기능 유지·핵심 이해관계자 협의가 필요하며 실행가능성을 기준으로 전환안을 비교해야 한다. 해체 단계에서는 이해관계자의 손실을 최소화하는 정리 방안을 검토할 수 있다. 점검·결정·집행·재평가의 회복 루프를 논하는 것이 모델의 실무적 시사점이다."},{"heading":"Ⅶ. 결론과 답안의 표현상 유의","text":"퀸·카메론의 4단계는 성장에 따른 조직 내부의 관리과제 변화를, 위첼·존슨의 5단계는 환경 및 내부 변화의 조기 인식 실패가 쇠퇴로 확대되는 경로를 설명한다. 두 모형 모두 조직의 적응역량과 관리행동이 중요하다는 점에서 연결되지만 단계의 수와 명칭, 설명목적은 다르다. 답안에서는 4단계를 순서대로 기술하고, 요구된 다섯 조직특성을 표로 비교하고, 별도로 쇠퇴 5단계를 제시한 다음 예방적 조치를 설명한다. 특정 연구의 개념을 다른 연구자 이름으로 잘못 표기하지 않았는지 마지막으로 검토한다."},{"heading":"Ⅷ. 다섯 가지 비교기준을 사례로 설명","text":"창업 1년 차의 작은 조직은 창업자가 제품 기획과 채용을 직접 결정하고, 자원 확보와 고객발굴에 대부분의 에너지를 투입할 수 있다. 집단성이 높아지면 구성원의 공유된 사명과 협업문화가 중요한 자원이 되지만 직무경계와 보고체계는 여전히 유연하다. 종업원 수와 사업영역이 늘어 공식화 단계로 이동하면 업무와 성과의 책임 소재를 명료화하기 위해 조직도·인사규정·회계절차·결재권한을 확립한다. 정교화 단계에서는 여러 사업부가 서로 다른 시장에서 기민하게 대응하도록 분권화하면서도 품질·윤리·전략 조정 등 공동 기준을 유지해야 한다. 이런 사례를 목표·리더십·구조·소통·통제라는 다섯 축에 나누어 배치하면 단계를 단순 나열하는 답안과 구별된다."},{"heading":"Ⅸ. 쇠퇴 단계별 지표와 전략 연결","text":"맹목 단계의 특징은 고객불만·기술변화·직원 이탈 같은 선행신호를 정식 지표에 담지 못하는 것이다. 무대응 단계에서는 하락 지표가 보고되더라도 '일시적 현상'으로 간주하여 근본원인 분석과 결정이 지연된다. 잘못된 행동 단계에서는 무리한 규모 확장이나 단기비용 삭감처럼 문제의 원인을 악화시키는 처방이 나타날 수 있다. 위기 단계에서는 운영자금·핵심고객·기술인력 확보 여부가 회생의 시간제약이 되며, 해체 단계에서는 경영주체로서의 존속 가능성이 근본적으로 약화된다. 경영자가 늦게 대응할수록 선택 가능한 대안이 줄어든다는 연속적 과정이 중요하다. 성장 자체가 쇠퇴를 막는다는 보장은 없으므로 신규 사업의 투자수익률과 핵심 역량의 재생산성도 지속적으로 검토해야 한다."},{"heading":"Ⅹ. 연구모형의 한계와 결론","text":"조직의 수명주기라는 용어는 조직이 반드시 생명체처럼 같은 순서로 태어나 성장한 뒤 소멸한다는 뜻은 아니다. 기술기업·공기업·비영리조직은 자원구조와 규제환경이 달라 단계의 장단점이 다르게 나타날 수 있다. 초기부터 정교한 통제를 요구받는 산업이 있고, 성숙한 조직에서도 신규 사업부가 창업단계처럼 운영될 수 있다. 그러므로 각 단계의 효과성 기준을 고정된 성패 기준이 아니라 환경과 조직 역량 사이의 적합성을 평가하는 질문으로 활용해야 한다. 쇠퇴모형 역시 회생 가능성이 언제나 보장된다고 단정하지 않고, 관찰되는 위험 지표와 대응 선택의 질을 구분해 논한다. 문제 요구의 물음 1·2·3을 별개의 소제목으로 정리하는 것이 답안 작성의 우선 과제다."},{"heading":"Ⅷ. 다섯 가지 비교기준을 사례로 설명","text":"창업 1년 차의 작은 조직은 창업자가 제품 기획과 채용을 직접 결정하고, 자원 확보와 고객발굴에 대부분의 에너지를 투입할 수 있다. 집단성이 높아지면 구성원의 공유된 사명과 협업문화가 중요한 자원이 되지만 직무경계와 보고체계는 여전히 유연하다. 종업원 수와 사업영역이 늘어 공식화 단계로 이동하면 업무와 성과의 책임 소재를 명료화하기 위해 조직도·인사규정·회계절차·결재권한을 확립한다. 정교화 단계에서는 여러 사업부가 서로 다른 시장에서 기민하게 대응하도록 분권화하면서도 품질·윤리·전략 조정 등 공동 기준을 유지해야 한다. 이런 사례를 목표·리더십·구조·소통·통제라는 다섯 축에 나누어 배치하면 단계를 단순 나열하는 답안과 구별된다."},{"heading":"Ⅸ. 쇠퇴 단계별 지표와 전략 연결","text":"맹목 단계의 특징은 고객불만·기술변화·직원 이탈 같은 선행신호를 정식 지표에 담지 못하는 것이다. 무대응 단계에서는 하락 지표가 보고되더라도 '일시적 현상'으로 간주하여 근본원인 분석과 결정이 지연된다. 잘못된 행동 단계에서는 무리한 규모 확장이나 단기비용 삭감처럼 문제의 원인을 악화시키는 처방이 나타날 수 있다. 위기 단계에서는 운영자금·핵심고객·기술인력 확보 여부가 회생의 시간제약이 되며, 해체 단계에서는 경영주체로서의 존속 가능성이 근본적으로 약화된다. 경영자가 늦게 대응할수록 선택 가능한 대안이 줄어든다는 연속적 과정이 중요하다. 성장 자체가 쇠퇴를 막는다는 보장은 없으므로 신규 사업의 투자수익률과 핵심 역량의 재생산성도 지속적으로 검토해야 한다."},{"heading":"Ⅹ. 연구모형의 한계와 결론","text":"조직의 수명주기라는 용어는 조직이 반드시 생명체처럼 같은 순서로 태어나 성장한 뒤 소멸한다는 뜻은 아니다. 기술기업·공기업·비영리조직은 자원구조와 규제환경이 달라 단계의 장단점이 다르게 나타날 수 있다. 초기부터 정교한 통제를 요구받는 산업이 있고, 성숙한 조직에서도 신규 사업부가 창업단계처럼 운영될 수 있다. 그러므로 각 단계의 효과성 기준을 고정된 성패 기준이 아니라 환경과 조직 역량 사이의 적합성을 평가하는 질문으로 활용해야 한다. 쇠퇴모형 역시 회생 가능성이 언제나 보장된다고 단정하지 않고, 관찰되는 위험 지표와 대응 선택의 질을 구분해 논한다. 문제 요구의 물음 1·2·3을 별개의 소제목으로 정리하는 것이 답안 작성의 우선 과제다."},{"heading":"Ⅺ. 수명주기 판단의 다면적 기준","text":"조직규모만으로 단계가 확정되지는 않는다. 매출·인원 증가와 별개로 권한위임 수준, 의사소통 방식, 공식규정의 정착 정도, 혁신과 지식공유 역량을 함께 관찰해야 한다. 예를 들어 인원이 적더라도 엄격한 인증·품질관리가 필요한 사업은 초기부터 공식화가 강할 수 있고, 인원이 많더라도 신규 연구개발조직은 탐색과 창업적 의사결정이 중요할 수 있다. 이런 차이를 표에 덧붙이면 모형의 실제 적용범위와 한계를 구별하여 서술할 수 있다."}],"sources":[{"author":"Quinn & Cameron 모형을 분석한 학술 요약","year":2014,"title":"Organizational Life Cycle – Four Stages","url":"https://getd.libs.uga.edu/pdfs/saxton_cenina_b_201412_edd.pdf"},{"author":"Weitzel & Jonsson","year":1989,"title":"Decline in Organizations: A Literature Integration and Extension","url":"https://eric.ed.gov/?id=EJ388705"}],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-econ-3":{"parts":[{"heading":"Ⅰ. 두 이론의 식별문제","text":"인적자본이론에서는 교육이 지식·기술·문제해결 능력을 높이므로 교육 후 생산성이 실제로 향상되고 임금이 이를 반영한다. 신호이론에서는 교육이 생산성을 직접 높이지 않더라도 학력을 취득하는 비용이 능력 유형에 따라 다를 경우 생산성이 높은 사람을 분별하는 신호가 될 수 있다. 임금과 학력이 관찰상 양(+)의 관계라는 사실만으로 어느 설명이 참인지 확정할 수 없다. 능력의 자기선택, 교육의 인과 효과, 채용시장의 정보 비대칭을 구분해야 한다. 정책적으로 인적자본 축적과 정보신호에 쓰이는 사회적 지출은 서로 다른 후생효과를 낳을 수 있다."},{"heading":"Ⅱ. 교육재정의 정책적 함의","text":"교육이 생산성을 향상시키고 지식 확산 등의 외부효과를 낳는다면 정부의 고등교육 재정지원은 사적 투자보다 작은 교육투자를 보정할 여지가 있다. 반면 교육의 일부가 단순히 고능력자를 선별하는 비용이라면 학위 취득 경쟁에 사회적 비용이 과도하게 투입될 수 있다. 이는 모든 대학교육이 낭비라는 의미가 아니라 인적자본 효과와 신호효과의 비중을 실증적으로 구분해야 한다는 뜻이다. 교육 기회의 형평성, 소득이 낮은 학생의 유동성 제약, 재정의 기회비용과 대체 신호의 가능성도 정책평가 항목이다."},{"heading":"Ⅲ. 분리균형의 유인제약 도출","text":"고졸자의 생애소득 현재가치를 2억원, 대졸자를 X억원이라고 두자. 고능력자가 대학을 택할 조건은 X−0.5≥2, 즉 X≥2.5다. 저능력자가 대학을 택하지 않을 조건은 2≥X−1.5, 즉 X≤3.5다. 따라서 약한 유인제약을 충족하는 분리 조건은 2.5≤X≤3.5억원이다. 양쪽 유형이 무차별이 아니라 각자 선택을 엄격히 선호하기를 요구한다면 2.5<X<3.5억원이다. 예컨대 X=3억원이면 고능력자의 대학순편익 2.5억원은 고졸 2억원보다 크고, 저능력자의 대학순편익 1.5억원은 고졸 2억원보다 작다. 표에는 두 유형의 교육비와 순소득을 교차시켜 보여주면 검산하기 쉽다."},{"heading":"Ⅳ. 결론과 균형의 전제","text":"분리균형은 대학을 선택한 사람을 고능력자로 믿는 기업의 임금정책이 자기선택과 양립할 때 설명된다. 문제에 주어진 비용 차이만으로 모든 신호균형이 언제나 존재한다고 단정할 수는 없고, 대학 이수 여부가 실제로 관찰 가능하고 기업의 기대와 임금결정이 일관되어야 한다. 경계값에서는 무차별 유형의 행동을 지정하는 추가 조건이 필요하다. 계산결과를 제시한 뒤 교육의 생산성 효과와 신호효과를 혼동하지 않는 것으로 답안을 마무리한다."},{"heading":"Ⅴ. 수치별 자기선택 비교표","text":"X가 2.5억원 미만이면 고능력자도 대학 순소득이 고졸 2억원에 못 미칠 수 있어 대학을 통해 능력을 분리하기 어렵다. X가 3.5억원보다 크면 저능력자도 대학 순소득이 고졸 2억원을 초과하게 되어 학력 신호를 모방하려는 유인이 생긴다. 2.5억원과 3.5억원 사이에서는 고능력자는 대학, 저능력자는 고졸을 선택한다는 분리 조건을 만족한다. 두 경계값에서 개인이 무차별이라면 추가적인 행동 규칙이 필요하다. 이 구간을 단순히 '고능력자는 대학 비용이 더 싸다'라고 외우기보다 소득 증가분 X−2와 각 유형 비용 0.5·1.5억원을 비교하는 유인제약으로 도출해야 한다."},{"heading":"Ⅴ. 수치별 자기선택 비교표","text":"X가 2.5억원 미만이면 고능력자도 대학 순소득이 고졸 2억원에 못 미칠 수 있어 대학을 통해 능력을 분리하기 어렵다. X가 3.5억원보다 크면 저능력자도 대학 순소득이 고졸 2억원을 초과하게 되어 학력 신호를 모방하려는 유인이 생긴다. 2.5억원과 3.5억원 사이에서는 고능력자는 대학, 저능력자는 고졸을 선택한다는 분리 조건을 만족한다. 두 경계값에서 개인이 무차별이라면 추가적인 행동 규칙이 필요하다. 이 구간을 단순히 '고능력자는 대학 비용이 더 싸다'라고 외우기보다 소득 증가분 X−2와 각 유형 비용 0.5·1.5억원을 비교하는 유인제약으로 도출해야 한다."},{"heading":"Ⅵ. 학습용 결론","text":"신호모형의 분리조건은 고능력자의 교육 선택 유인과 저능력자의 비선택 유인을 동시에 충족해야 한다. 한쪽 유형만 유리한 수준은 분리균형이 아니다. 문제에서 주어진 비용 0.5억원과 1.5억원을 모두 사용해 경계값을 구하고, 경계에서는 무차별에 대한 추가 조건이 필요하다는 점을 명시하면 논리의 완결성이 높아진다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-econ-3":{"parts":[{"heading":"Ⅰ. 독점적 노조모형의 선택변수","text":"독점적 노동조합은 임금수준을 결정하고 기업은 주어진 임금에 대해 노동수요에 따라 고용을 조정한다고 가정한다. 노동수요 w=100−0.5L은 고용 L이 늘수록 기업이 지불할 최대 임금이 낮아지는 관계를 보여준다. 노조의 효용 U=wL은 임금과 고용의 곱이므로 임금만 높이는 것과 조합원의 총임금소득을 극대화하는 것은 다르다. 시장에서 반드시 근로자가 원하는 고용과 노조가 원하는 고용이 같지는 않다. 그래프는 수평축 고용 L, 수직축 임금 w로 두고 노동수요와 노조의 무차별곡선을 함께 그린다."},{"heading":"Ⅱ. 물음 1·2 계산의 검산","text":"L=60을 요구하면 기업의 노동수요상 지급 가능 임금은 w=100−0.5×60=70이다. 그러나 이것은 최적화에서 나온 값이 아니다. 효용함수에 수요식을 대입하면 U(L)=(100−0.5L)L=100L−0.5L², 일계조건 100−L=0에서 L*=100, 이계조건 −1<0으로 최대임을 확인한다. 따라서 w*=50, U*=5,000이다. L=60일 때 효용은 70×60=4,200이므로 노조의 목표 효용과 다름을 숫자로 확인할 수 있다. 수요곡선의 수평축 절편 L=200 및 수직축 절편 w=100을 표시하면 최대화 지점이 수요곡선의 중점이라는 사실도 쉽게 드러난다."},{"heading":"Ⅲ. 수요 탄력성 변화의 조건부 비교","text":"일반화한 선형 노동수요를 w=a−bL(b>0)로 놓으면 U=aL−bL², 최적 고용 L*=a/(2b), 임금 w*=a/2, 노조효용 U*=a²/(4b)이다. 수직 절편 a를 고정하면서 기울기 b가 작아지는 상황이라면 수요가 평탄해지고 고용과 총효용이 증가하지만 최적 임금은 a/2로 변하지 않는다. 그러나 수요곡선이 회전하는 중심점이나 절편의 변화까지 포함해 '탄력적'이 되면 결과가 달라질 수 있다. 예를 들어 a까지 하락하면 최적 임금도 하락한다. 따라서 문제 조건만으로 임금·고용·효용이 일률적으로 모두 증가한다고 표현하면 과잉 일반화이다. 변화 가정을 그래프의 이동·회전으로 명시한 뒤 조건부 결론을 내려야 한다."},{"heading":"Ⅳ. 결론과 답안 점검","text":"독점적 노동조합은 임금-고용 상충관계를 노동수요 제약 아래에서 조정한다. 수요의 탄력성은 임금 인상으로 잃는 고용의 크기와 직접 연결되므로 노조가 중시하는 목표에 영향을 준다. 본 예시에서는 L=60일 때 w=70, 효용극대화 시 L=100·w=50·U=5,000이 핵심 계산 결과다. 대수계산과 그래프 결과가 일치하는지 점검하고, 탄력성 변화에 대한 설명에서 기울기와 절편을 분리한다."},{"heading":"Ⅴ. 수학적 범위와 비교정태의 한계","text":"원문에서는 '더 탄력적으로 변한다'는 진술만 있으므로 특정한 함수 변화방식이 제시되지 않는 한 한 가지 숫자 결론을 강요할 수 없다. 예시로 임금 절편 a=100을 유지하고 기울기가 b=0.5에서 b=0.25로 작아진다면 최적 고용은 100→200, 최적 임금은 50으로 일정, 노조 효용은 5,000→10,000으로 증가한다. 하지만 임금 절편이 동시에 감소하면 이 결론을 그대로 사용할 수 없다. 비교정태의 전제를 명시하고 조건부 결과를 산출한 다음 실제 정책·시장환경을 단정하지 않는 것이 학술적으로 더 정확하다."},{"heading":"Ⅴ. 수학적 범위와 비교정태의 한계","text":"원문에서는 '더 탄력적으로 변한다'는 진술만 있으므로 특정한 함수 변화방식이 제시되지 않는 한 한 가지 숫자 결론을 강요할 수 없다. 예시로 임금 절편 a=100을 유지하고 기울기가 b=0.5에서 b=0.25로 작아진다면 최적 고용은 100→200, 최적 임금은 50으로 일정, 노조 효용은 5,000→10,000으로 증가한다. 하지만 임금 절편이 동시에 감소하면 이 결론을 그대로 사용할 수 없다. 비교정태의 전제를 명시하고 조건부 결과를 산출한 다음 실제 정책·시장환경을 단정하지 않는 것이 학술적으로 더 정확하다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-hr-3":{"parts":[{"heading":"Ⅰ. 구조화 면접과 비구조화 면접의 정의","text":"구조화 면접은 직무분석에 근거하여 핵심 직무역량을 정하고, 지원자 전원에게 유사한 문항과 순서·평가기준을 적용하는 방식이다. 행동사례형 질문은 과거의 실제 행동을, 상황제시형 질문은 가정적 직무문제에 대한 판단과 대응을 확인할 수 있다. 비구조화 면접은 질문 내용·순서 및 추적질문을 면접관 재량에 맡겨 자연스러운 대화와 즉흥적인 탐색을 허용한다. 두 방식은 '질문이 자유로운가'뿐 아니라 평가의 표준화 정도와 점수 근거의 재현가능성에서 차이가 있다."},{"heading":"Ⅱ. 구조화 면접의 장점·한계","text":"구조화 면접은 모든 지원자에게 유사한 정보 수집 기회를 보장하므로 비교가능성이 높고, 평정척도와 행동기준을 사전에 고정하면 평가자별 기준 차이를 줄일 수 있다. 직무 관련 문항을 사용하면 평가 결과를 채용 후 직무성과와 연결해 타당도를 점검하기도 쉽다. 다만 직무분석, 평가기준과 면접관 훈련에 시간·비용이 필요하며, 새로운 역량이나 예상 밖의 강점을 파악하려면 통제된 후속질문 범위가 필요하다. 구조화 자체가 차별·편견을 자동으로 없애는 것은 아니므로 문항의 직무관련성과 집단별 불리한 영향을 지속 평가해야 한다."},{"heading":"Ⅲ. 비구조화 면접의 장점·한계","text":"비구조화 면접은 상황에 맞춰 깊이 있는 후속 질문을 진행하고 지원자의 경험 맥락을 다각도로 이해할 수 있다. 초기 조직문화 탐색이나 매우 전문적인 직무의 예비 대화에서 유연성이 유용할 수 있다. 그러나 면접관마다 다른 질문을 하면 지원자 간 공정한 비교가 어렵고, 첫인상·후광효과·유사성 편향·확증편향에 평가가 흔들릴 수 있다. 그 결과 점수의 재현가능성과 기록의 투명성이 약해진다. 지원자의 자기표현 능력과 실제 직무수행 능력을 혼동하지 않도록 주의해야 한다."},{"heading":"Ⅳ. 비교표·운영 개선안과 결론","text":"비교표의 기준을 문항 표준화, 평가척도, 정보 탐색의 유연성, 평가자 간 신뢰도, 실시비용·시간으로 설정한다. 실무에서는 구조화 면접을 기본으로 하되 공통 평가문항을 모두 소화한 다음 사전에 정한 범위의 추가 질문을 허용하는 혼합설계가 가능하다. 복수 면접관의 독립 채점, 행동기준 예시, 면접관 훈련, 기록 보존과 예측타당도 검증을 실시하면 두 방식의 장단점을 조정할 수 있다. 답안은 개념·장점·단점 각각을 분리해 설명한 뒤 선발의 타당성·공정성을 고려한 선택기준으로 끝맺는다."},{"heading":"Ⅴ. 현장 운영사례 비교","text":"고객민원 담당자를 선발할 때 구조화 면접은 '민원인의 요구와 제도상 처리기준이 충돌한 경험을 설명하라'라는 공통 행동 질문을 사용하고, 상황 파악·규정 준수·설명력·감정관리의 행동기준에 따라 평가할 수 있다. 비구조화 면접에서는 면접관이 지원자의 관심사와 경험을 자유롭게 탐색하므로 맥락이 풍부하지만 실제로 모든 지원자가 같은 역량을 평가받는지 확인하기 어렵다. 동일한 지원자가 면접관에 따라 매우 다른 점수를 받는다면 평가자 간 신뢰도가 낮은 것이다. 구조화 도구의 효과는 면접질문과 실제 직무성과가 연결되는지, 지원자 집단의 불리한 영향을 모니터링하는지에 따라 달라질 수 있다."},{"heading":"Ⅵ. 답안의 결론과 작성 순서","text":"출제의 핵심은 두 기법의 정의와 장점·단점을 각각 구분해 비교하는 것이다. 답안지는 ① 구조화 면접 정의 ② 구조화 장점 ③ 구조화 한계 ④ 비구조화 정의 ⑤ 비구조화 장점 ⑥ 비구조화 한계 ⑦ 타당도·공정성 비교와 개선책 순서로 쓰면 논점 누락을 줄일 수 있다. 직접 비교기준을 동일하게 유지하지 않고 한 기법은 비용, 다른 기법은 공정성만 논하면 비교의 설득력이 약하다. 공식 채점자료가 없는 상태에서 예상 점수를 매기는 대신 요건별 설명의 충실도와 사례의 적합성을 점검하는 것이 적절하다."},{"heading":"Ⅴ. 현장 운영사례 비교","text":"고객민원 담당자를 선발할 때 구조화 면접은 '민원인의 요구와 제도상 처리기준이 충돌한 경험을 설명하라'라는 공통 행동 질문을 사용하고, 상황 파악·규정 준수·설명력·감정관리의 행동기준에 따라 평가할 수 있다. 비구조화 면접에서는 면접관이 지원자의 관심사와 경험을 자유롭게 탐색하므로 맥락이 풍부하지만 실제로 모든 지원자가 같은 역량을 평가받는지 확인하기 어렵다. 동일한 지원자가 면접관에 따라 매우 다른 점수를 받는다면 평가자 간 신뢰도가 낮은 것이다. 구조화 도구의 효과는 면접질문과 실제 직무성과가 연결되는지, 지원자 집단의 불리한 영향을 모니터링하는지에 따라 달라질 수 있다."},{"heading":"Ⅵ. 답안의 결론과 작성 순서","text":"출제의 핵심은 두 기법의 정의와 장점·단점을 각각 구분해 비교하는 것이다. 답안지는 ① 구조화 면접 정의 ② 구조화 장점 ③ 구조화 한계 ④ 비구조화 정의 ⑤ 비구조화 장점 ⑥ 비구조화 한계 ⑦ 타당도·공정성 비교와 개선책 순서로 쓰면 논점 누락을 줄일 수 있다. 직접 비교기준을 동일하게 유지하지 않고 한 기법은 비용, 다른 기법은 공정성만 논하면 비교의 설득력이 약하다. 공식 채점자료가 없는 상태에서 예상 점수를 매기는 대신 요건별 설명의 충실도와 사례의 적합성을 점검하는 것이 적절하다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-hr-2":{"parts":[{"heading":"Ⅰ. 바이오데이터의 의미와 평가대상","text":"바이오데이터(biographical data)는 지원자가 과거에 수행한 활동·교육·직무경험·성과·역할 등을 구조화된 문항으로 수집해 미래 직무성과의 예측에 활용하는 인사선발 자료다. 단순 이력서와 달리 문항별 채점규칙과 직무 관련성을 사전에 정의하며, 자기소개 문장의 문학적 완성도와는 구별된다. 경험의 축적이 직무성과와 상관된다는 점을 활용하되, 과거경험이 반드시 성과의 인과 원인임을 전제하지 않아야 한다. 직무별 성과준거가 서로 다르면 동일한 문항 세트를 모든 직군에 적용하기 어렵다."},{"heading":"Ⅱ. 장점과 실제 활용","text":"적절히 설계된 바이오데이터는 다수 지원자에게 동일한 기준을 적용하므로 서류심사의 일관성과 처리 효율성을 높일 수 있다. 조직에 이미 존재하는 행동·경험 정보를 활용할 수 있고, 직무 관련성이 확보되면 면접·시험 등의 추가 자료와 함께 예측모형을 개선할 수 있다. 예컨대 고객응대직무에서 실제 민원 처리 경험의 유형과 피드백 대응 행동은 학위나 전공 명칭보다 직무 관련 행동의 단서를 제공할 수 있다. 다만 경험의 기회 자체가 지원자마다 불평등했을 수 있으므로 이를 점수에 반영하는 정당성을 검토해야 한다."},{"heading":"Ⅲ. 한계와 공정성·개인정보 위험","text":"지원자의 과거 행동은 자기보고로 수집될 때 과장과 회상오류가 생길 수 있고, 생활환경·인구통계적 이력은 보호받아야 할 특성의 대리변수가 될 수 있다. 과거 데이터에서 높은 예측력을 보인 변수가 직무나 환경이 바뀐 뒤에도 유효하다는 보장은 없다. 또한 비직무적 사생활 정보의 과잉 수집은 개인정보 위험을 낳는다. 따라서 문항의 직무관련성, 최소 수집원칙, 민감정보 제외, 목적 외 이용 방지, 보존기간과 접근권한, 차별적 효과 모니터링을 함께 설계해야 한다. 자기보고 왜곡을 막기 위한 증빙 요구도 필요한 범위로 제한해야 한다."},{"heading":"Ⅳ. 개발절차와 교차타당화","text":"먼저 직무분석을 통해 성공적인 수행에 필요한 행동과 성과준거를 정하고, 이를 측정할 후보 경험문항을 개발한다. 이후 대표적인 표본에서 응답과 실제 성과 자료를 수집해 신뢰도·예측타당도를 분석한다. 우연한 표본 특성이 과도하게 반영되지 않도록 독립 표본에서 교차타당화하고 문항 및 가중치를 조정한다. 운영 중에는 직무변화, 응답 왜곡, 집단별 영향, 예측력 저하를 지속 점검하고 필요하면 재설계한다. 개발단계는 직무분석→문항작성→예비시험·표본 수집→준거 측정→통계분석→교차검증→운영 재평가로 쓰면 명확하다."},{"heading":"Ⅴ. 설계·평가표의 구성","text":"답안에는 개발절차를 표 형태로 나누어 '직무분석: 어떤 행동이 성과와 관련되는가', '문항개발: 어떤 과거경험을 어떻게 질문하는가', '시범검사: 문항에 오해·왜곡이 있는가', '타당도검증: 실제 직무성과를 예측하는가', '공정성점검: 불필요한 집단차별이 있는가', '운영개선: 직무·조직 변화에 따라 수정하는가'라고 대응시키면 된다. 경험을 단순히 많이 했는지보다 경험이 직무 요구와 얼마나 밀접하게 연결되는지를 평가해야 한다. 자료 축적의 편의를 위해 직무 관련성이 낮은 개인정보를 과도하게 보유하는 것은 도구의 장점이 아니다."},{"heading":"Ⅵ. 준거와 타당도의 주의","text":"개발 표본에서 문항 점수와 성과 사이에 높은 상관관계가 나타나도 같은 자료로 문항을 고르고 정확도를 재측정하면 실제 예측력을 과대평가할 수 있다. 독립 표본을 통한 교차검증과 주기적 재점검이 필요하다. 준거가 상사의 주관평가에만 의존한다면 성과준거 자체의 편향도 검토해야 한다. 따라서 직무 관련성, 신뢰도, 예측타당도, 평가 형평성과 개인정보보호를 분리하여 설명해야 출제의 장단점 및 개발단계 요구를 모두 충족한다."},{"heading":"Ⅴ. 설계·평가표의 구성","text":"답안에는 개발절차를 표 형태로 나누어 '직무분석: 어떤 행동이 성과와 관련되는가', '문항개발: 어떤 과거경험을 어떻게 질문하는가', '시범검사: 문항에 오해·왜곡이 있는가', '타당도검증: 실제 직무성과를 예측하는가', '공정성점검: 불필요한 집단차별이 있는가', '운영개선: 직무·조직 변화에 따라 수정하는가'라고 대응시키면 된다. 경험을 단순히 많이 했는지보다 경험이 직무 요구와 얼마나 밀접하게 연결되는지를 평가해야 한다. 자료 축적의 편의를 위해 직무 관련성이 낮은 개인정보를 과도하게 보유하는 것은 도구의 장점이 아니다."},{"heading":"Ⅵ. 준거와 타당도의 주의","text":"개발 표본에서 문항 점수와 성과 사이에 높은 상관관계가 나타나도 같은 자료로 문항을 고르고 정확도를 재측정하면 실제 예측력을 과대평가할 수 있다. 독립 표본을 통한 교차검증과 주기적 재점검이 필요하다. 준거가 상사의 주관평가에만 의존한다면 성과준거 자체의 편향도 검토해야 한다. 따라서 직무 관련성, 신뢰도, 예측타당도, 평가 형평성과 개인정보보호를 분리하여 설명해야 출제의 장단점 및 개발단계 요구를 모두 충족한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-org-2":{"parts":[{"heading":"Ⅰ. 리더-구성원 교환관계의 의미","text":"LMX(Leader-Member Exchange)는 리더의 행동이 모든 구성원에게 일률적으로 나타나는 것만이 아니라 리더와 각 구성원 사이에 형성되는 교환관계의 질에 따라 달라질 수 있음을 설명한다. 높은 질의 관계에서는 신뢰·존중·상호 의무와 정보·지지의 교류가 활발할 수 있다. 낮은 질의 관계에서는 공식적 직무계약과 역할 수행 중심의 거래가 주가 된다. 관계의 질은 구성원의 태도·협력·성과 등과 연관될 수 있지만 단순히 리더 개인의 호감과 동일한 개념은 아니다."},{"heading":"Ⅱ. 교환관계의 형성과 갈등","text":"초기에 리더와 구성원은 조직이 지정한 역할과 업무수행을 통해 서로에 관한 정보를 얻는다. 과제수행의 신뢰성, 의사소통, 상호지원, 책임감과 공정한 기대 형성이 누적되면 역할의 경계가 조정되고 보다 자율적인 교환이 가능해진다. 다만 리더가 특정 구성원에게 기회와 정보를 집중하면 팀 내 불공정 인식이 생길 수 있으므로, 고품질의 개별관계를 넓히는 동시에 성과와 역량개발 기회를 투명하게 배분해야 한다. 일시적 친분이나 단편적 성과만으로 누군가를 내부인·외부인으로 고정하지 않아야 한다."},{"heading":"Ⅲ. Graen·Uhl-Bien 3단계","text":"낯선 관계(stranger phase)는 고용계약·공식 역할에 기초한 제한적 교환 단계다. 친숙한 관계(acquaintance phase)는 리더와 구성원이 상호신뢰·지지 가능성을 시험하며 책임과 정보공유의 범위를 점차 확대하는 단계다. 성숙한 동반자 관계(mature partnership phase)는 높은 수준의 신뢰와 존중, 상호의무를 바탕으로 공통목표를 위해 자율적으로 협력하는 단계다. 각 단계의 교환대상, 역할범위, 의사소통과 상호책임을 표로 비교하면 좋다. 이 단계 모델이 구성원 모두에게 자동으로 적용되는 결정론적 경로는 아니라는 점을 덧붙인다."},{"heading":"Ⅳ. 실무적 적용과 결론","text":"리더는 초기의 공정한 역할 부여와 피드백을 기반으로 구성원 모두에게 관계 발전의 기회를 제공해야 한다. 구성원 역시 책임 있는 직무수행, 건설적인 의사표현 및 협력을 통해 상호 신뢰 형성에 기여할 수 있다. 다만 LMX의 관계 질을 성과평가나 인사결정에서 개인적 친분으로 환원하는 것은 제도의 공정성과 충돌한다. 답안은 개념과 형성 메커니즘을 설명한 다음 세 단계의 교환 특성을 차례로 비교하고, 관계차별의 위험과 조직관리상 시사점으로 끝맺는다."},{"heading":"Ⅴ. LMX 단계별 대화 예시와 차이","text":"신입사원이 직무에 배치된 초기는 리더가 규정상 역할과 기대성과를 설명하고 구성원이 이를 수행하는 낯선 관계에 가깝다. 이후 구성원이 예측 가능한 성과와 책임감을 보이고 리더가 적절한 피드백과 재량을 부여하면 친숙한 관계로 전환될 수 있다. 장기적으로 업무에 관한 상호신뢰와 자율성이 높아지면 구성원이 개선제안을 먼저 내고 리더가 이를 의사결정에 반영하는 성숙한 동반자 관계가 형성될 수 있다. 이 예시는 단계의 특징을 설명하기 위한 것이지 실제 구성원을 고정된 내부인·외부인으로 분류하는 기준은 아니다."},{"heading":"Ⅵ. 관계의 질과 관리상 한계","text":"관계가 성숙하더라도 직무관련 정보와 개발기회가 불공정하게 배분되면 팀 전체의 신뢰가 저하될 수 있다. 리더는 개별적 지지와 객관적인 보상·평가의 기준을 구분해야 하며, 성숙한 관계에 있는 구성원에게도 윤리적 경계와 책임이 필요하다. LMX의 고품질 관계를 모든 구성원에게 넓히려는 노력은 수단이지만, 이를 단순히 호감을 얻는 기술로 오해해서는 안 된다. 답안에서는 형성 과정에 영향을 주는 상호행동과 3단계 교환특성을 연결하면 논증이 자연스러워진다."},{"heading":"Ⅴ. LMX 단계별 대화 예시와 차이","text":"신입사원이 직무에 배치된 초기는 리더가 규정상 역할과 기대성과를 설명하고 구성원이 이를 수행하는 낯선 관계에 가깝다. 이후 구성원이 예측 가능한 성과와 책임감을 보이고 리더가 적절한 피드백과 재량을 부여하면 친숙한 관계로 전환될 수 있다. 장기적으로 업무에 관한 상호신뢰와 자율성이 높아지면 구성원이 개선제안을 먼저 내고 리더가 이를 의사결정에 반영하는 성숙한 동반자 관계가 형성될 수 있다. 이 예시는 단계의 특징을 설명하기 위한 것이지 실제 구성원을 고정된 내부인·외부인으로 분류하는 기준은 아니다."},{"heading":"Ⅵ. 관계의 질과 관리상 한계","text":"관계가 성숙하더라도 직무관련 정보와 개발기회가 불공정하게 배분되면 팀 전체의 신뢰가 저하될 수 있다. 리더는 개별적 지지와 객관적인 보상·평가의 기준을 구분해야 하며, 성숙한 관계에 있는 구성원에게도 윤리적 경계와 책임이 필요하다. LMX의 고품질 관계를 모든 구성원에게 넓히려는 노력은 수단이지만, 이를 단순히 호감을 얻는 기술로 오해해서는 안 된다. 답안에서는 형성 과정에 영향을 주는 상호행동과 3단계 교환특성을 연결하면 논증이 자연스러워진다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-econ-2":{"parts":[{"heading":"Ⅰ. 수요독점과 임금차별의 차이","text":"수요독점 기업은 노동의 한계수입생산(MRPL)과 추가 채용비용을 비교해 고용을 선택한다. 모든 근로자에게 동일한 임금을 지급하는 경우, 한 사람을 더 고용하려면 기존 근로자들의 임금도 인상해야 할 수 있다. 따라서 한계고용비용 MCE는 일반적으로 노동공급 S보다 위에 위치하며, 이윤극대화 기업은 MRPL=MCE에서 고용량을 정하고 그 고용량에 대응하는 S곡선 위의 임금을 지급한다. 완전한 1급 임금차별이 가능하면 근로자마다 개별 유보임금만 지불할 수 있어 추가 고용비용이 공급곡선과 같아진다. 이 경우 MRPL=S까지 고용하므로 단일임금 수요독점보다 고용량이 커질 수 있다."},{"heading":"Ⅱ. 그래프의 필수 표식","text":"그래프의 가로축에는 고용 L, 세로축에는 임금·한계고용비용·한계수입생산을 놓는다. 우상향 공급 S, 그보다 가파르게 상승하는 MCE, 우하향 MRPL을 그리고, 단일임금 수요독점의 선택고용 L_M을 MRPL=MCE의 교점에서 수직으로 내린다. 지급임금 w_M은 L_M의 공급곡선상 높이에서 읽는다. 완전 차별의 고용량 L*은 MRPL=S의 교점이며, 모든 노동자에게 하나의 임금이 지급된다고 잘못 적지 않는다. 제시된 모형에 따라 근로자별 지급임금이 서로 다르다는 점이 두 체제의 본질적 차이다."},{"heading":"Ⅲ. 최저임금이 MCE를 바꾸는 경로","text":"완전 차별의 경쟁적 기준 임금과 단일임금 수요독점 임금 사이에 최저임금을 설정하면 단일임금 기업이 채용을 확대하는 구간에서 한계고용비용이 일정한 최저임금 수준을 따라 수평이 된다. 최저임금이 공급과 교차하는 고용량을 넘어서면 추가 채용을 위해 기존 근로자의 임금도 인상해야 하므로 한계비용은 원래의 곡선 형태로 연결될 수 있다. 따라서 적정 수준의 최저임금은 수요독점의 고용제약을 완화하면서 임금과 고용을 동시에 높일 가능성이 있다. 그러나 최저임금이 높아져 MRPL을 넘어가면 고용 감소가 발생할 수 있다. 정책효과는 설정 수준과 원래 곡선의 위치에 의존하며, 그래프 없는 일반화는 위험하다."},{"heading":"Ⅳ. 비교 결론","text":"완전 차별에서는 개별 근로자의 유보임금만 지급할 수 있다는 강한 정보가정이 필요하고, 단일임금 수요독점에서는 기존 근로자의 임금인상 부담이 추가 고용을 제약한다. 적정 최저임금은 이러한 제약을 부분적으로 보정할 수 있지만 모든 수요독점에서 항상 고용을 증가시키는 것은 아니다. 물음 1에서는 두 고용결정과 임금결정 방식을, 물음 2에서는 최저임금 도입 이후 MCE의 모양과 선택점 변화를 그래프에 연결해 설명하면 된다."},{"heading":"Ⅴ. 노동시장 수요독점의 정책적 의미","text":"수요독점의 중요한 특징은 고용주의 시장지배력이 존재할 때 노동의 한계수입생산과 개별 근로자의 지급임금 사이에 격차가 발생할 수 있다는 점이다. 임금차별의 정도와 노동공급 탄력성, 고용주에 대한 이동제약이 달라지면 근로자후생과 총잉여의 분배도 달라진다. 최저임금 도입은 단순한 비용상승일 뿐 아니라 단일임금 수요독점의 한계채용비용을 변화시키는 정책이 될 수 있다. 따라서 완전경쟁 모형의 최저임금 결과를 그대로 복사하지 않고, 수요독점 모형의 S·MCE·MRPL 세 곡선과 교차점을 기준으로 설명해야 한다. 이 문제에서 임금은 해당 고용량의 공급곡선에서 읽고, 이윤극대화 고용량은 한계비용과 한계수입생산의 교점에서 정한다."},{"heading":"Ⅴ. 노동시장 수요독점의 정책적 의미","text":"수요독점의 중요한 특징은 고용주의 시장지배력이 존재할 때 노동의 한계수입생산과 개별 근로자의 지급임금 사이에 격차가 발생할 수 있다는 점이다. 임금차별의 정도와 노동공급 탄력성, 고용주에 대한 이동제약이 달라지면 근로자후생과 총잉여의 분배도 달라진다. 최저임금 도입은 단순한 비용상승일 뿐 아니라 단일임금 수요독점의 한계채용비용을 변화시키는 정책이 될 수 있다. 따라서 완전경쟁 모형의 최저임금 결과를 그대로 복사하지 않고, 수요독점 모형의 S·MCE·MRPL 세 곡선과 교차점을 기준으로 설명해야 한다. 이 문제에서 임금은 해당 고용량의 공급곡선에서 읽고, 이윤극대화 고용량은 한계비용과 한계수입생산의 교점에서 정한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-hr-1":{"parts":[{"heading":"Ⅴ. 평가기법 간 통합과 운영상 유의","text":"속성접근법의 간편성은 대규모 평가운영에 유리하지만 직무행동으로 평가근거를 설명하기 어렵다는 약점이 있다. 행동접근법의 BARS는 관찰 가능한 행동사례로 점수 간 차이를 규정하므로 직무기반 피드백에 유용하지만 행동기준을 개발·유지하는 데 비용이 든다. 결과접근법의 MBO는 목표의 구체성과 성과 책임성을 높일 수 있으나 외부환경과 팀 기여를 반영하지 않으면 단기성과 편향이 생길 수 있다. 평가자의 후광효과·관대화 경향·최근성 편향을 줄이려면 평가자 교육, 근거 기록, 이의제기와 조정절차가 필요하다. 실제로는 속성·행동·결과를 상호보완적으로 결합하되 각 요소의 직무관련성과 측정가능성, 피평가자 수용성을 검토해야 한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2022-hr-1":{"parts":[{"heading":"Ⅵ. 세 평가체계의 연결과 결론","text":"커크패트릭 모형의 반응·학습·행동·결과는 교육 직후의 만족도에서 현장행동 변화와 조직성과까지 평가수준을 넓혀 간다. 골드스타인의 타당도 관점은 교육내용의 직무관련성과 훈련에서 관찰된 학습이 실제 직무상황으로 이전되는지 확인하는 데 의미가 있다. ROI는 교육의 금전적 편익에서 비용을 차감하여 투자비용 대비 성과를 보는 수단이지만 교육 외 경영환경 변화의 영향을 통제하지 않으면 효과를 과대평가할 수 있다. 따라서 세 모형은 동일한 것이 아니며, 단계별 평가자료와 성과 귀속의 한계를 구분해 기술해야 한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-econ-2":{"parts":[{"heading":"Ⅰ. 분리균형의 정보 구조","text":"기업은 채용 전에 개별 근로자의 생산성을 직접 볼 수 없지만 대학 이수 여부는 확인할 수 있다. 고능력자(H)의 생산성은 40, 저능력자(L)의 생산성은 25이며, 두 유형의 비중은 각각 절반이다. 대학 교육이 순수한 신호라는 가정에서는 교육 자체가 이 생산성 값을 변화시키지 않는다. 고능력자의 교육비용 4와 저능력자의 6이 다르므로 학력 선택으로 유형을 분리할 가능성을 검토한다. 다만 생산성 차이 15보다 교육비용 차이 2가 매우 작다는 점에서 단순 분리가 가능하다고 속단해서는 안 된다. 신호는 채용기업의 믿음과 교육 선택의 유인제약이 서로 일관될 때 작동한다."},{"heading":"Ⅱ. 유인제약의 수식과 실패 이유","text":"고능력자가 대학을 택하려면 대졸 임금 W_D에서 교육비용 4를 뺀 값이 비대졸 임금 W_N 이상이어야 한다. 즉 W_D−W_N≥4다. 저능력자가 비대학을 택하려면 W_N≥W_D−6, 즉 W_D−W_N≤6이어야 한다. 두 조건을 합치면 4≤W_D−W_N≤6이다. 완전 분리라고 가정할 때 기업의 경쟁적 임금은 각각 생산성과 같은 40과 25이므로 격차는 15다. 이 격차는 6보다 커서 저능력자가 대학에 진학하고자 하는 유인이 생긴다. 그러므로 완전 분리라는 가정과 개인의 최적선택이 양립하지 않아 주어진 단순한 신호 제도만으로 분리균형을 성립시킬 수 없다."},{"heading":"Ⅲ. 풀링 가능성과 임금의 범위","text":"두 유형 모두 교육을 선택하지 않는 등의 풀링 집단을 생각하면 해당 집단의 평균생산성은 0.5×40+0.5×25=32.5이다. 경쟁기업이 관찰되는 동일 집단을 구분할 수 없다면 집단에 대한 기대생산성 임금으로 이 값이 등장할 수 있다. 그러나 이 수치가 언제나 유일한 풀링균형임금을 뜻하지는 않는다. 관찰되지 않은 교육선택에 대해 기업이 어떤 믿음을 갖는지에 따라 비대졸·대졸 그룹의 임금제시와 개인의 전략이 달라질 수 있다. 문제의 물음2에서 분리균형이 성립하지 않았다는 이유만으로 H는 반드시 대학, L은 반드시 고졸이라고 단정하면 앞의 유인제약과 모순된다. 확정 가능한 계산과 추가 가정이 필요한 부분을 구분한다."},{"heading":"Ⅳ. 교육시장과 사회후생의 해석","text":"순수 신호교육은 생산성을 높이지 않으므로 같은 생산성의 근로자가 더 비싼 교육을 선택한다면 사회적으로 실질 비용이 소모될 수 있다. 학위증으로 정보비대칭을 줄이는 긍정적 역할이 있더라도, 신호경쟁이 과열될 경우 자격 취득의 사적 편익과 사회적 순편익이 일치하지 않는다. 교육비용의 개인차가 능력을 구분하기에 충분하지 않으면 과잉교육이나 학력 인플레이션이 나타날 수 있다. 다만 실제 고등교육에는 인적자본 축적의 기능도 있으므로 이 문제의 '교육은 생산성을 높이지 않는 순수 신호'라는 전제를 현실의 모든 교육에 일반화해서는 안 된다. 결론에서는 유인제약 불성립과 이론상 후생 문제를 분리해 기술한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"개인 선택의 유인과 기업의 기대생산성 임금이 서로 일치해야 균형이라는 점이 핵심이다. 고·저능력자 모두 대학에 가고자 하는 상태는 분리균형이라고 부를 수 없다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2022-econ-3":{"parts":[{"heading":"Ⅰ. 두 부문의 임금격차에 관한 기본 구조","text":"동일 산업에서 노조 조직 부문과 비조직 부문으로 노동시장이 나뉘고, 노조 설립 이전에는 두 부문의 임금수준이 같았다고 가정한다. 노조가 단체교섭을 통해 조직 부문의 임금을 높이면 두 부문 사이에 명목 임금격차가 생긴다. 그러나 조직 부문의 고임금이 기업의 노동수요를 줄이거나 신규채용을 위축시키면 일부 근로자가 비조직 부문으로 이동하여 비조직 임금도 달라질 수 있다. 관찰된 두 임금수준의 차이는 고용의 이동과 구성 변화가 반영된 결과이므로 노조가 직접 올린 금액과 동일하지 않을 수 있다. 기본 그래프에는 각 부문의 노동수요·공급 및 근로자 이동을 함께 나타낸다."},{"heading":"Ⅱ. 조직 부문 임금인상과 파급효과","text":"첫 번째 격차 확대효과는 노조의 임금 프리미엄이다. 교섭력이 충분하면 조직 기업의 임금이 기존 균형보다 높아지고 동일한 조건의 근로자에게 직접 임금상승이 발생한다. 두 번째는 파급 또는 밀어내기(spillover) 효과다. 노조 부문에서 일할 수 없게 된 일부 근로자가 비노조 부문의 취업을 구하면서 그 부문의 노동공급이 늘면, 수요곡선이 일정하다는 가정 아래 비노조 임금에 하방 압력이 작용한다. 따라서 두 효과가 동시에 발생할 때 임금격차가 더 커질 수 있다. 고용 이동은 직업·기술·지역 이동비용에 따라 제한될 수 있으므로 이동인원과 임금변화를 정량적으로 확정할 수는 없다."},{"heading":"Ⅲ. 위협효과와 대기실업효과의 반대 방향","text":"위협효과(threat effect)는 비노조 기업이 구성원의 노동조합 조직화를 예방하려고 임금과 근로조건을 자발적으로 개선하는 현상이다. 이는 비노조 임금이 상승해 조직·비조직 부문의 격차를 좁히는 방향으로 작용할 수 있다. 대기실업(wait unemployment)은 고임금 노조 일자리를 얻기 위해 비노조 일자리 또는 즉시취업을 포기하고 대기하는 선택을 의미한다. 일부 노동자가 비노조 부문의 공급에서 빠지면 공급 감소를 통해 비노조 임금에 상승압력을 줄 수 있다. 위협효과는 기업의 예방적 임금결정에서, 대기실업은 근로자의 구직전략에서 출발하므로 기제를 혼동해서는 안 된다. 두 효과의 실제 크기는 정보와 노동이동 비용 등에 의존한다."},{"heading":"Ⅳ. 단순 임금격차가 인과효과가 아닌 이유","text":"두 부문의 근로자들이 동일한 능력·경력·직무를 갖는다고 보장되지 않는다. 규모가 큰 기업이나 생산성이 높은 산업·지역에 노조가 더 많다면 관찰된 차이는 기업과 근로자의 선택효과를 포함한다. 기업 규모, 직무, 경력, 교육, 성별·연령 등의 통제변수를 넣어도 측정되지 않는 능력·조직 문화·경영성과가 남을 수 있다. 노조 조직 전후의 동일 근로자를 비교하거나 유사 기업을 대조하고, 제도적 변화에 따른 준실험 자료를 확보하는 등의 방법이 인과효과 추정에 필요하다. 결론에서는 조직부문의 직접효과, 비조직으로의 파급, 위협효과와 대기실업효과를 각각 구분하고 임금격차 자체를 노조의 '순수 인과효과'로 동일시하지 않는다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"따라서 첫 물음의 임금격차 확대 요인과 두 번째 물음의 격차 축소 가능 요인을 서로 다른 화살표로 그래프에 그리면 시각적으로 명확해진다. 노동조합이 임금을 올린다는 단순 명제만으로 비조직 부문에 나타나는 복합 효과까지 설명할 수는 없다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2025-hr-2":{"parts":[{"heading":"Ⅰ. 조직형태 구분의 기준","text":"기업별 노동조합은 특정 기업의 근로자를 주요 조직기반으로 하며 동일한 기업의 인사·임금·작업환경을 교섭 주제로 삼기 쉽다. 직업별 노동조합은 숙련기술과 직종의 공동성, 산업별 노동조합은 동일 산업에 종사하는 근로자의 이해, 일반노동조합은 직종·산업을 가로지르는 광범한 조직대상을 중심으로 형성된다. 이 분류는 무엇을 단위로 가입과 조합원 관계를 형성하는지의 차이다. 상급단체에 가입한 사실만으로 개별 노조의 단위조직 형태가 자동으로 바뀌는 것은 아니다. 산별노조 내부에 기업별 지부·지회가 존재할 수도 있으므로 조직형태와 내부 구성단위를 구분한다."},{"heading":"Ⅱ. 기업별·직업별 노조의 조직관리","text":"기업별 노조는 사업장 구성원의 현안 파악과 고충처리, 회사 의사결정에 대한 대응이 비교적 용이하다. 그러나 기업의 성과·재정과 조합원의 조건이 긴밀하게 연결되어 구조조정과 기업 간 임금격차의 영향을 크게 받을 수 있다. 직업별 노조는 직업의 전문성, 자격·숙련기준, 교육훈련 체계에 관한 공동 이해를 바탕으로 조합원을 관리할 수 있다. 특정 숙련의 공급조건이나 직업적 진입통로를 교섭력의 근거로 활용할 수 있지만, 직종 간 이해가 다양한 노동시장 전체를 대표하기에는 한계가 있을 수 있다."},{"heading":"Ⅲ. 산업별·일반노조의 조직관리","text":"산업별 노조는 다수 기업에 걸친 공통 임금기준과 산업 내 고용조건을 협의할 수 있어 기업 간 지나친 근로조건 격차를 줄이는 데 관심을 가질 수 있다. 반면 업종의 대기업과 중소기업, 정규직과 다양한 고용형태의 이해가 서로 다를 때 내부 조정이 과제가 된다. 일반노조는 소규모 사업장, 비전형 고용 등 전통적 사업장 단위의 교섭조직으로 포섭하기 어려운 근로자의 조직화를 넓힐 수 있다. 그러나 조직기반이 폭넓을수록 공동 의제의 선택과 재정·대표성 조정의 복잡성이 커질 수 있다. 각 조직형태의 강점은 해당 노동시장의 구조에 따라 달라진다."},{"heading":"Ⅳ. 노동시장 통제와 결론","text":"기업별 노조는 주로 특정 기업 내 인사·임금배분과 작업조건을 교섭 대상으로 삼고, 직업별 노조는 해당 직종의 숙련공급과 자격의 유지, 산업별 노조는 업종 간·기업 간 임금표준화와 교섭조정, 일반노조는 다양한 근로자의 조직적 대표성과 사회적 영향력에 중점을 둘 수 있다. 그러나 조직형태 그 자체가 특정 불법행위나 진입제한 권한을 자동으로 부여하는 것은 아니다. 노동시장 통제란 조합의 조직력·교섭력과 제도적 대표성이 임금·고용조건에 미치는 영향을 분석하는 개념으로 이해해야 한다. 답안에서는 형태마다 조직원리·기반·관리 특징·노동시장 영향을 일대일 대응하여 제시한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"예컨대 동일 지역에서 대기업·중소기업의 임금차이가 클 때 기업별 노조와 산업별 노조는 교섭 단위와 공통 임금규범 설정에서 다른 선택을 할 수 있다. 직업별 노조는 해당 직업에서 요구하는 숙련 형성과 진입 경로를 관리의 핵심 의제로 삼을 수 있고, 일반노조는 다양한 종사 형태의 공통 권익을 모색할 수 있다. 어떤 조직이 더 적합한지는 산업구조와 근로자의 이동가능성, 대표성에 대한 제도적 규범에 따라 달라진다. 따라서 각 유형의 차이는 임금수준의 높고 낮음이 아니라 조직기반과 노동시장에 개입하는 경로에서 설명해야 한다."},{"heading":"Ⅵ. 평가시 주의","text":"조직형태를 비교할 때는 조직기반과 교섭 범위, 직무의 동질성, 산업 내 기업 규모 차이, 근로자 이동가능성을 별도의 기준으로 제시하여 결론을 명료하게 한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2022-hr-3":{"parts":[{"heading":"Ⅰ. 사용자 교섭전략의 기본 전제","text":"노사관계에서 사용자의 교섭전략은 노동조합의 요구를 어떻게 이해하고 공동의 합의 가능성을 찾을 것인가에 관한 대응 선택이다. 포용·압박·회피라는 구분은 교섭 상대방에 대한 인식과 활용하는 수단에서 차이가 있다. 실제 교섭은 법률상 단체교섭 의무와 노사관계의 장기적 신뢰라는 제약 아래에서 이루어진다. 따라서 이론상의 압박전략을 곧바로 위법한 부당노동행위의 허용 근거로 취급하거나, 회피전략을 법률상 교섭요구의 무조건적 거부로 이해해서는 안 된다. 각 전략의 개념을 먼저 정의하고 실행수단 두 가지를 분명히 제시한다."},{"heading":"Ⅱ. 포용전략의 개념과 실행수단 둘","text":"포용전략은 노조를 합법적 이해관계자로 인정하고 공동의 문제해결·신뢰 형성을 통해 교섭을 진행하는 방법이다. 첫째, 정례적 노사협의와 공동검토팀을 구성하여 경영상의 제약과 근로자 요구를 사전에 공유하고 쟁점별 대안을 발굴할 수 있다. 둘째, 교섭 과정에서 생산성 개선이나 교육훈련을 연계한 상호이익적 선택지를 제시해 임금·근로조건의 개선과 기업의 지속가능성을 함께 고려할 수 있다. 장점은 갈등 비용과 불확실성을 줄이고 합의의 수용성을 높인다는 점이다. 그러나 정보공개 범위와 합의 가능한 자원이 제한될 경우 시간과 신뢰 형성 비용이 클 수 있다."},{"heading":"Ⅲ. 압박전략의 개념과 실행수단 둘","text":"압박전략은 사용자 측의 협상력과 상대방이 부담할 비용을 고려하여 요구 수준을 낮추거나 양보를 끌어내려는 접근이다. 예를 들어 첫째, 사전 재무분석을 토대로 수용 가능한 제안의 상한과 일정·단계별 대안을 엄격히 설정할 수 있다. 둘째, 합법적 범위 내에서 교섭의 우선순위를 명확히 하고 상호 교환조건을 구체화해 상대방이 제안의 비용과 대안을 비교하도록 유도할 수 있다. 다만 협상에서 정당한 경제적 주장과 교섭 거부·노조 활동에 대한 불이익 등 법률상 금지되는 행위를 혼동하지 않아야 한다. 과도한 압박은 갈등 장기화와 협력관계의 훼손으로 이어질 수 있다."},{"heading":"Ⅳ. 회피전략의 개념과 실행수단 둘","text":"회피전략은 특정 쟁점에 대한 직접적인 대립을 늦추거나 교섭의 초점을 조정하여 현재의 갈등을 최소화하려는 접근이다. 첫째, 추가적인 자료가 필요하거나 이해관계가 급격히 변하는 쟁점에 관해 기한을 정한 공동 사실조사를 실시할 수 있다. 둘째, 합의 가능한 주제를 먼저 처리하고 난도가 높은 쟁점은 별도 분과에서 검토하도록 일정과 절차를 분리할 수 있다. 이 경우도 정당한 교섭 요구를 무기한 무시하거나 회피해 법률상 의무를 위반하는 선택은 정당화되지 않는다. 장점은 감정적 충돌을 완화한다는 것이고, 단점은 핵심 문제의 해결이 지연되고 신뢰가 떨어질 수 있다는 점이다."},{"heading":"Ⅴ. 종합 비교와 적용기준","text":"포용은 협력관계를 활용한 상호이익 탐색, 압박은 수용 가능한 제안의 한계와 협상력을 활용한 대응, 회피는 충돌의 시점과 과제를 조정하는 전략으로 요약된다. 장기적 협력 필요성이 크고 정보공유가 가능한 쟁점에서는 포용의 효용이 높을 수 있다. 재무적 제약이 명확하고 이행가능성에 관한 경계설정이 필요할 때는 합법적인 범위에서 단호한 입장이 필요하다. 불확실한 사안은 쟁점의 범위를 정해 추가 조사와 교섭일정을 병행할 수 있다. 시험장 답안에서는 전략마다 반드시 실행수단 두 개를 별도 번호로 적고, 교섭 거부나 부당노동행위를 권장하는 표현을 피해야 한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"실전에서는 포용·압박·회피 각각의 정의 아래 '실행①, 실행②'를 명확히 분리해 적는다. 대응행동의 구체성은 높이되 현실법상 허용 여부가 확인되지 않은 압박수단은 시험 당시 법령 대조 전까지 학습용 승인 답안에 포함하지 않는 편이 안전하다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2024-경영조직론|1|2":{"parts":[{"heading":"Ⅴ. 던컨 모형의 두 축을 사용하는 이유","text":"환경의 복잡성은 의사결정과 관련된 외부 요인의 수·이질성에 관한 문제이고, 환경의 동태성은 그 요인들이 얼마나 자주·예측하기 어렵게 변하는지에 관한 문제다. 요인이 적고 변화도 느린 단순·안정 환경에서는 관련 정보를 비교적 쉽게 파악할 수 있어 낮은 불확실성이 나타난다. 반면 요인이 많고 빠르게 변하는 복잡·동태 환경에서는 정보수집과 예측이 어렵다. 두 차원을 구분하지 않으면 정보의 '양'과 변화의 '속도'를 같은 개념으로 섞어 쓰게 된다. 불확실성은 외부변화 그 자체뿐 아니라 의사결정자가 정보를 충분히 얻고 해석할 수 있는지의 문제임을 강조한다."},{"heading":"Ⅵ. 네 환경 유형별 조직구조 대응","text":"단순·안정 환경에서는 비교적 표준화된 직무와 중앙집중적 관리로 업무를 효율화할 수 있다. 복잡·안정 환경에서는 전문부서와 전문가를 활용하여 다양한 외부요인에 대응하되, 변화속도는 낮으므로 공식적인 부서 간 조정장치도 활용할 수 있다. 단순·동태 환경에서는 외부요인 수가 적더라도 변화의 속도가 빠르므로 현장 재량과 신속한 정보순환이 중요하다. 복잡·동태 환경에서는 여러 전문영역이 동시에 빠르게 움직이므로 분권화, 수평 협업, 경계연결 역할과 조직 간 정보 공유가 필요할 수 있다. 이 대응은 절대적 규칙이 아니라 환경과 구조의 적합성을 판단하는 방향이다."},{"heading":"Ⅶ. 구조적 복잡성과 정보처리 능력","text":"복잡한 환경일수록 모든 정보를 최고경영자 한 사람에게 집중하는 방식은 판단지연을 낳을 수 있다. 전문부서는 환경의 다른 측면을 깊게 이해할 수 있지만, 부서마다 다른 목표를 추구하면 통합비용이 커진다. 그래서 조직은 분화와 통합을 함께 고려해야 한다. 부서간 프로젝트팀, 경계연결 담당자, 정례적인 정보교류와 공동 성과목표는 이질적인 전문지식을 모으는 장치가 될 수 있다. 반면 안정적 업무까지 지나치게 유연한 팀 구조로 운영하면 책임이 불명확해질 수 있다. 환경 불확실성에 따라 정보처리 부담과 관리비용을 비교해야 한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"조직구조의 정답은 환경유형 하나만으로 고정되지 않는다. 외부 정보수집에 드는 비용, 전문인력의 공급, 부서 간 조정 필요성, 경영자의 의사결정 능력 등이 함께 영향을 준다. 분권화가 필요한 환경이라도 공통 안전기준·윤리규범을 유지할 중앙조정 장치가 필요할 수 있다. 불확실성은 환경요인의 복잡성과 변화성이라는 두 축으로 판별하고, 대응구조는 정보처리 역량이라는 관점에서 평가하는 것으로 결론을 정리한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2024-인사노무관리론|3|0":{"parts":[{"heading":"Ⅳ. 관대화·편견·대조 오류의 작동기제","text":"관대화 경향은 평가자가 다수의 피평가자에게 실제 성과보다 높은 점수를 주는 체계적 왜곡이다. 이는 조직 전체에서 '잘못을 지적하기 어렵다'는 분위기나 보상 갈등을 피하려는 동기에서 심화될 수 있다. 편견은 성별·학력·출신·개인적 친분 등 직무와 무관한 선호나 고정관념이 특정 사람의 평가에 영향을 미치는 현상이다. 대비오류는 바로 직전에 평가한 매우 우수한 직원과의 상대적 비교 때문에 평균적인 직원도 낮게 평가하는 것처럼 비교 순서가 평정에 영향을 주는 문제다. 세 오류는 평가를 왜곡하지만 원인과 해결책이 동일하지 않다."},{"heading":"Ⅴ. 오류별 예방기법과 기록의 중요성","text":"관대화 경향을 줄이려면 절대평정척도에 구체적인 행동기준을 넣고 평가자별 평정분포를 점검할 수 있다. 편견을 막으려면 직무관련 증거를 중심으로 평가하고 적절한 평가자 훈련과 이의신청·조정 절차를 운영한다. 대비오류에는 동일한 기간의 성과자료와 공통 기준을 활용하고, 한 사람을 직전 평가자와 직접 비교하기보다 객관적인 직무수행 기준에 맞춰 판단하도록 한다. 다면평가를 도입하더라도 동일한 편견이 여러 평가자에게 존재한다면 문제를 완전히 제거하지 못한다. 평가의 신뢰성·타당성은 점수만큼 근거 기록과 절차의 일관성에 달려 있다."},{"heading":"Ⅵ. 비교 결론","text":"관대화는 여러 구성원의 점수가 상향으로 치우치는 '평가수준' 오류, 편견은 특정 속성에 따른 '평가대상' 오류, 대비오류는 직전 또는 주변 사람을 기준으로 판단하는 '평가순서·상대비교' 오류라는 차이를 갖는다. 답안에는 각 정의마다 한 가지 조직사례를 붙이고, 원인·영향·예방책을 병렬로 비교하면 출제 요구를 충족하기 쉽다. 평가제도의 공정성과 직무 타당도를 높이는 것이 세 오류를 줄이는 공동목표이지만 해결책은 각각 맞춤형이어야 한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"예를 들어 모든 직원에게 5점 만점을 주는 것은 관대화 오류의 후보이고, 동일한 성과인데 특정 학교 출신이라는 이유로 1점을 낮추는 것은 편견이다. 평범한 성과의 직원을 특별히 우수한 직원 바로 다음에 평가해 실제보다 낮게 보는 것은 대비오류다. 이처럼 같은 평가결과 하락이라도 원인을 구별해야 예방책이 맞아떨어진다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2024-인사노무관리론|1|1":{"parts":[{"heading":"Ⅴ. 임금수준·체계·형태를 구분하는 기준","text":"임금수준은 기업이 시장과 경영상 여건을 고려하여 전체 임금의 높이를 결정하는 문제다. 대외적 경쟁력, 인건비 부담, 인재확보·유지에 영향을 준다. 임금체계는 기본급이 직무가치·직능·연공·성과 등 어떤 기준으로 사람과 직무 사이에 배분되는지를 결정한다. 임금형태는 시간급·월급·성과급처럼 임금이 어떤 단위와 방식으로 산정·지급되는지의 문제다. 예를 들어 평균 임금총액이 같아도 직무급 비중과 성과급 설계에 따라 내부 공정성과 동기부여 효과가 달라질 수 있다. 이 셋의 의사결정 수준을 혼동하지 않아야 한다."},{"heading":"Ⅵ. 임금관리 설계의 공정성","text":"임금수준은 동일한 직무를 수행하는 다른 기업과 비교하는 외부적 공정성과 관련되고, 임금체계는 조직 내부의 서로 다른 직무·역할 간 비교에 영향을 준다. 임금형태는 성과의 측정방식과 지급시점에 따라 변동성과 소득 안정성, 행동유인을 바꾼다. 공정한 임금관리에는 시장 조사, 직무분석 및 직무평가, 성과측정의 신뢰성, 법적 최저기준과 차별금지 원칙의 준수가 필요하다. 어느 한 요소가 우수해도 다른 요소가 불합리하면 조직 구성원의 수용성과 동기부여가 낮아질 수 있다."},{"heading":"Ⅶ. 유형별 장단점과 실무적 조화","text":"연공 중심 체계는 장기근속과 숙련 축적을 뒷받침할 수 있지만 직무가치 및 최근 성과와의 연계가 약해질 수 있다. 직무 중심 체계는 직무가치에 따른 명료한 보상을 가능하게 하지만 직무변화와 역할의 유연성을 평가하기 어려울 수 있다. 성과급은 목표달성 유인을 높일 수 있으나 측정가능한 지표에 과도하게 집중하여 협업·안전·장기품질을 희생할 위험이 있다. 그래서 기업은 조직의 전략과 직무 특성에 따라 수준·체계·형태를 결합한다. 시험장에서는 세 개념과 각 관리의 목적, 대표적인 대안을 일관된 표로 제시하고 결과와 한계를 연결해 설명한다."},{"heading":"Ⅴ. 출제 요구와 오류 점검","text":"임금관리의 세 요소를 답안에서 잘 구분하는 가장 쉬운 방법은 각 요소에 하나씩 의사결정 질문을 붙이는 것이다. 수준관리는 '우리 회사의 총임금이 시장 대비 어느 정도인가', 체계관리는 '어떤 직무·사람에게 얼마를 배분하는가', 형태관리는 '그 돈을 어떤 단위와 조건으로 지급하는가'를 묻는다. 시장 경쟁력, 내부 공정성, 지급의 동기효과를 연계하되 서로 같은 개념으로 혼동하지 않는다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2026-인사노무관리론|2|0":{"parts":[{"heading":"Ⅴ. 선발도구의 타당성과 신뢰성","text":"신뢰성이란 반복 측정이나 평가자 간 비교에서 점수가 얼마나 일관되게 나타나는가를 뜻한다. 타당성은 그 점수가 실제로 측정하려는 직무 관련 능력이나 성과준거를 적절히 반영하는가에 관한 것이다. 신뢰성은 타당성을 위한 필요조건 가운데 하나일 수 있으나 신뢰성이 높다고 도구가 반드시 타당한 것은 아니다. 예를 들어 면접관들이 동일하게 응답자의 외모를 선호한다면 점수는 일치해도 직무능력을 적절히 측정하지 못할 수 있다. 직무분석을 통해 평가하는 구성개념을 먼저 정의하고 예측준거와의 관계를 확인해야 한다."},{"heading":"Ⅵ. 채용현장의 적용과 효율성","text":"직무관련 타당도가 높아도 시행비용이 과도하고 지원자의 접근성을 지나치게 제한하면 조직의 선발효율성이 낮아질 수 있다. 선발도구의 비용에는 문항개발, 평가자 교육, 지원자 응시, 채점, 재검증에 들어가는 자원이 포함된다. 인지능력검사는 대규모 평가에 유리할 수 있지만 해당 직무에서 측정하려는 역량과의 적합성을 확인해야 한다. 평가센터법은 여러 평가자가 다수 과제를 관찰해 풍부한 행동자료를 얻는 대신 운영비용이 크다. 서류·시험·면접을 조합할 때 각 도구가 서로 중복되지 않는 정보를 제공하는지 살피면 선택의 효율성을 높일 수 있다."},{"heading":"Ⅶ. 공정성과 채용절차의 수용성","text":"지원자들은 선발절차의 목적과 평가기준이 투명하고 합리적인지에 민감하게 반응한다. 직무와 무관한 질문, 불필요한 개인정보 수집, 평가기회의 불균등은 선발의 공정성과 신뢰를 손상시킬 수 있다. 동일한 기준을 모든 지원자에게 기계적으로 적용하는 것만으로 충분하지 않으며 장애·접근성 등 정당한 조정의 필요성도 검토해야 한다. 평가자는 채점근거를 남기고 이의제기 경로를 준비해 절차적 공정성을 높일 수 있다. 단, 채용 관련 법령의 구체적인 의무는 시험 당시 시행본과 원문을 별도로 확인해야 한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2023-hr-3":{"parts":[{"heading":"Ⅰ. 두 제도의 설계 목적과 시간 관리","text":"선택적 근로시간제는 일정한 정산기간 동안 근로자가 실제 업무 시작과 종료시간을 스스로 정할 수 있게 하는 제도다. 핵심은 배분 결정권에 근로자 자율이 있다는 점이다. 반면 탄력적 근로시간제는 업무량의 성수기와 비수기에 맞춰 기간별 근로시간을 미리 배치하되 정해진 평균 기준과 법적 요건을 충족하도록 설계한다. 따라서 선택제는 개인의 시간선택, 탄력제는 기간별 총근로시간의 배분이라는 측면에서 출발점이 다르다. 둘 다 특정 조건에서 유연한 근무를 가능하게 하지만, 누가 일정을 결정하는지와 어떤 기준기간으로 계산하는지는 다르다."},{"heading":"Ⅱ. 근로자 관점의 장점과 한계","text":"선택적 근로시간제의 장점은 개인이 통근·가족 돌봄·집중업무 시간에 맞춰 스케줄을 조정할 수 있다는 것이다. 자율성이 보장될수록 직무만족과 시간 활용의 효율성이 높아질 수 있다. 그러나 공통 협업시간을 정하지 않으면 부서 간 연락·회의가 어려워지고, 명목상 자율과 실제 사용자 지시 사이에 차이가 생길 수 있다. 탄력적 근로시간제는 업무량이 적은 기간에 근로를 줄일 수 있지만 성수기에는 근로시간이 집중되어 피로와 건강 부담이 발생할 수 있다. 두 제도 모두 휴식·예측가능성·근로자 의사소통을 함께 검토해야 한다."},{"heading":"Ⅲ. 기업 관점의 장점과 한계","text":"선택적 제도는 개인의 집중력과 전문성을 활용하기 좋은 지식노동·프로젝트 업무에서 유용할 수 있다. 기업은 출퇴근 관리보다 성과물과 협업 기한에 중점을 두어야 하며, 팀 단위 일정을 조정하는 관리비용이 든다. 탄력적 제도는 계절성 생산·정기 마감처럼 업무 수요가 변동하는 분야에서 인력 수급과 초과근로 부담을 조정하는 데 도움이 될 수 있다. 다만 일정 통지가 늦거나 특정 기간 과도한 근로를 유발하면 안전과 인력유지 측면에서 부작용이 생긴다. 각각의 장단점을 근로자와 사용자 두 관점에서 별도 표로 비교하면 문제 요구에 잘 맞는다."},{"heading":"Ⅳ. 시험 당시 적용법의 검증 주의","text":"유연근로시간제의 허용요건, 근로자대표와의 합의, 정산기간·단위기간 및 연장근로 계산은 법령 개정의 영향을 받을 수 있다. 따라서 이 답안에서 구체 기간이나 한도를 단정해 기입하기 전에 2023년 시험 당시 시행된 근로기준법·시행령·부칙 원문과 행정해석을 대조해야 한다. 인사관리상의 장단점을 설명하는 것과 법적 운영요건을 적시하는 것은 서로 다른 검증 단계다. 답안 검토표에서는 법령 적용 부분을 HOLD로 표시하고 원문 근거가 확보된 후 확정한다."},{"heading":"Ⅴ. 선택권과 탄력 배분을 오해하지 않는 방법","text":"선택적 근로시간제는 제도를 도입했다고 해서 언제나 아무 시간에나 출퇴근할 수 있다는 뜻은 아니다. 협업을 위한 공통 시간대나 업무상 필수 연락시간을 정할 수 있지만 그 결정과 운영은 근로자의 자기결정 범위와 양립해야 한다. 탄력적 근로시간제 역시 일시적인 근로시간 증가가 무제한 허용된다는 의미가 아니며, 사전 배분과 휴식, 평균근로시간 관리라는 제약을 전제로 한다. 기업의 사업 성수기 대응과 구성원의 건강을 동시에 살펴야 한다. 법적 도입 절차와 합의·통지 기준이 중요하지만 구체적인 기한·단위기간을 2023년 시험 당시 시행법령 검증 없이 암기문장에 확정하지 않는다. 시험장에서 필요한 것은 두 제도의 정의와 시간선택의 주체, 개인과 기업의 장단점을 구분하는 것이다."},{"heading":"Ⅵ. 실전 결론","text":"실무에서는 근로자 자율성의 실질 보장, 업무집중기와 비집중기의 안전·건강 관리, 업무상 협업 조정과 시간기록의 정확성을 동시에 고려해야 한다. 개인과 기업 어느 한쪽의 편익만 논하면 출제 요구에 미흡하다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2024-인사노무관리론|1|2":{"parts":[{"heading":"Ⅵ. DB·DC의 위험부담과 운영 차이","text":"DB형은 퇴직 때 지급할 급여가 사전에 정해지는 방식이므로 적립금 운용실적에 따라 사용자가 추가 부담을 질 수 있다. 따라서 기업은 장래 퇴직급여 지급의무와 적립 부족 위험을 관리해야 한다. 근로자는 급여 예측가능성이 높지만 지급시점과 임금상승·계속근로기간의 관계가 중요하다. DC형은 사용자의 정해진 부담금이 개인 계좌에 적립되어 가입자가 운용성과의 위험과 기회를 갖는다. 가입자에게는 상품 선택과 운용 교육이 중요하고, 운용성과의 변동성이 급여에 영향을 준다. 어느 방식이 반드시 유리한지 단정하기보다 근속예상기간·임금상승·위험감수성에 따른 차이를 설명한다."},{"heading":"Ⅶ. IRP의 기능과 제도상 구별","text":"개인형퇴직연금(IRP)은 퇴직하거나 이직하면서 받은 급여를 개인 계좌에 보존·이전하고 추가 저축할 수 있는 수단이다. DB·DC가 주로 사업장 단위에서 퇴직급여를 형성하는 구조를 다룬다면 IRP는 퇴직 후 개인의 급여 통산과 장기 운용에 초점을 둔다. 가입자가 직접 운용하며 수령방식 및 세제 문제와 연결되지만, 세액공제의 세부한도와 인출 요건은 해당 시점 법령에 따라 달라질 수 있으므로 당시 시행기준 확인이 필요하다. 시험장에서는 세 제도를 '급여 확정 여부', '부담금 확정 여부', '운용위험 부담 주체', '계좌 소유·통산 기능'으로 비교하면 구별이 명확하다."},{"heading":"Ⅷ. 수급권 보호와 법령 확인","text":"퇴직연금제도의 취지는 장래 지급될 퇴직급여를 외부에 적립하고 근로자의 노후 소득을 지키는 데 있다. 그러나 실제 사업장에서 요구되는 최소 적립수준, 사용자와 근로자의 선택권, IRP 이전과 예외사유, 중도인출 등 세부요건은 연도별 법령·감독규정 확인이 필요하다. 이 답안은 DB·DC·IRP의 경제적 구조를 비교하는 학습용으로만 사용하고 2024년 시험 당시 확정된 조문·부칙과 개별 적용을 대조하기 전까지 법률 내용 승인 표시를 하지 않는다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2026-인사노무관리론|1|1":{"parts":[{"heading":"Ⅴ. 조직의 경력욕구와 인력계획","text":"조직 차원의 경력개발은 필요한 인력을 적시에 확보하고 적합한 직무에 배치하며, 핵심 직무의 후계자를 미리 준비하려는 활동이다. 이를 위해 단기적인 결원 충원계획뿐 아니라 향후 필요한 역량, 사업변화에 따른 직무 전환, 핵심인력의 이탈 가능성을 함께 분석한다. 구성원의 장기 목표를 모른 채 일방적으로 직무를 바꾸면 인재유지에 역효과가 날 수 있으므로, 경력상담과 인사정보를 연결할 필요가 있다. 경력욕구는 인재 확보·배치·유지·승계에 대한 조직의 필요라는 관점에서 구분해 쓰면 명확하다."},{"heading":"Ⅵ. 경력경로의 다양화","text":"기존에는 승진이 경력발전의 대표적 신호였지만 수평적 조직구조와 전문직무 증가로 관리직 승진만으로 모든 구성원의 성장욕구를 충족하기 어렵다. 관리자와 전문가의 이중경력경로, 직무순환, 프로젝트 파견, 직무 심화, 경력상담과 멘토링 등이 대안이 될 수 있다. 각 제도를 도입할 때는 핵심 역량을 어떻게 측정하고 새로운 경력경로에서 보상·인정이 어떻게 이루어지는지 설계해야 한다. 관리자 경로와 전문경로가 명목상으로만 분리되고 보상·성장기회가 불평등하면 제도의 수용성이 낮아질 수 있다."},{"heading":"Ⅶ. 개인·조직 욕구의 조정과 성과","text":"개인은 자아실현·안정·전문성·일과 삶의 조화 등을 중시하지만 조직은 사업목표에 필요한 역량과 직무배치를 우선할 수 있다. 두 필요가 충돌하는 경우 경력대화로 개인의 선호와 조직의 현실적 기회를 확인하고 교육·직무이동·경력전환의 단계를 협의해야 한다. 경력개발의 성과는 단순한 교육참가 횟수보다 역량 향상, 내부 충원율, 승계준비도, 핵심인재 유지 및 직무만족 등으로 평가할 수 있다. 답안에서는 이러한 성과지표를 조직의 경력전략과 연결하여 경력개발이 인사관리의 단독 프로그램이 아니라 전략적 인력관리 과정임을 강조한다."},{"heading":"Ⅷ. 경력전략 요약","text":"조직의 인재 수요와 개인의 경력욕구를 일치시키는 것이 경력개발의 핵심이다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2026-인사노무관리론|1|2":{"parts":[{"heading":"Ⅴ. 경력앵커의 자기개념과 경력선택","text":"샤인의 경력앵커는 조직에 들어오기 전부터 고정되어 있는 성격유형이라기보다 직업 경험을 통해 개인이 자신의 능력·동기·가치를 학습하면서 형성하는 자기개념에 가깝다. 조직이 제안하는 승진이나 직무가 객관적으로 좋아 보여도 개인의 핵심 가치와 충돌하면 전직이나 이동을 고려할 수 있다. 예를 들어 기술전문성을 중시하는 구성원에게 관리직 승진만을 보상경로로 제공하면 동기부여보다 전문성 상실의 우려가 커질 수 있다. 따라서 경력앵커 진단은 일방적 인사배치의 근거가 아니라 경력상담의 출발점으로 활용하는 것이 적절하다."},{"heading":"Ⅵ. 여덟 유형의 직무경로 예시","text":"기술·기능적 역량형은 연구전문가·전문컨설턴트처럼 분야의 숙련을 깊게 할 수 있는 경로, 일반관리역량형은 여러 조직을 조정하고 책임지는 관리자 경로와 적합할 수 있다. 자율·독립형은 과제 결과에 대한 책임을 지되 일하는 방식의 재량이 큰 업무를, 안정·보장형은 예측가능한 고용·역할을 선호할 수 있다. 기업가적 창의성형은 창업·신사업개발, 봉사·헌신형은 공익·사회서비스, 순수도전형은 어려운 과제 해결, 라이프스타일형은 일·생활 균형을 실현할 수 있는 경력경로를 중시할 수 있다. 이는 가치의 우열이 아니라 서로 다른 동기 기준의 차이를 보여주는 사례다."},{"heading":"Ⅶ. 강점과 조직의 경력관리 전략","text":"개인의 핵심 동기가 존중되면 일에 대한 내재적 몰입과 경력만족을 높일 여지가 있다. 반대로 모든 사람을 한 가지 승진경로에 맞추면 다양한 전문성과 인재를 잃을 수 있다. 조직은 직무순환·전문가 트랙·프로젝트 운영·유연한 근로방식 등 경력경로의 선택지를 준비하고, 경력상담 과정에서 희망과 역량을 확인해야 한다. 경력앵커가 하나의 설문검사 결과로 영구 확정된다고 단정하기보다 경력경험과 생활조건의 변화도 고려해야 한다. 답안은 여덟 앵커의 가치와 강점을 각각 정확히 대응시키고 경력개발 실무에 적용하는 논리로 끝맺는다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."},"2026-인사노무관리론|3|0":{"parts":[{"heading":"Ⅴ. 여섯 숍 제도의 강제 수준 비교","text":"오픈 숍은 조합 가입이 고용의 조건이 아니어서 개인의 선택권이 크지만 조합의 조직유지 유인은 약할 수 있다. 클로즈드 숍과 유니언 숍은 채용·재직과 조합원 자격을 연결하는 방식이 서로 다르며 가입 의무의 강도가 높다. 에이전시 숍은 가입 자체와 비용부담을 구분하여 비조합원에게도 교섭대표 서비스에 대한 비용을 분담시키는 방식이다. 프레퍼렌셜 숍은 채용에서 조합원에게 선호를 부여하는 방식이며, 메인터넌스 숍은 일단 선택한 조합원 지위를 일정 기간 유지하도록 하는 방식이다. 이론적 분류와 국내법상 허용 여부는 별개이므로 후자를 단정하려면 적용시점 법령과 판례를 확인해야 한다."},{"heading":"Ⅵ. 체크오프의 실무적 기능과 위험","text":"체크오프(check-off)는 임금에서 조합비를 공제하여 노동조합에 전달하는 제도다. 노조는 회비징수 비용을 줄여 재정을 안정시킬 수 있고, 기업은 수납절차를 정형화할 수 있다. 그러나 임금 공제의 법적 근거, 조합원 개인의 의사, 노조 간 조직관계와 단체협약 내용이 충돌하면 분쟁이 생길 수 있다. 따라서 체크오프의 경제적 효율과 법적 정당성을 분리해 논해야 한다. 국내법상 임금 전액지급 원칙의 예외와 단체협약의 효력, 개별 공제 관련 판례 등은 2026년 시험 당시 근로기준법·노조법 원문과 직접 대조 후 확정한다."},{"heading":"Ⅶ. 가입제도와 재정제도의 구별","text":"숍 제도는 근로자의 조직 가입 여부와 조합의 조직력에 관한 장치이고, 체크오프는 조합비 징수절차와 재정기반에 관한 장치다. 가입의 강제가 강하다고 해서 조합비의 공제방식이 자동으로 정당화되는 것은 아니며, 조합에 가입하지 않을 자유 및 법정 보호요건과 조화를 이루어야 한다. 답안에서는 여섯 종류를 고용상 지위에 미치는 영향에 따라 비교하고, 마지막 별도 항목에서 체크오프의 개념·장단점·법적 검토 필요성을 제시한다. 법령·판례에 관한 개별 확정 승인 전까지는 내용검증 HOLD로 관리한다."}],"sources":[],"caution":"문항별 원문을 기준으로 구성한 학습용 확장 초안입니다. 시험 당시 법령·학설·학술 원전의 직접성 또는 공식 채점기준에 대한 독립 승인 없이 PASS 표시하지 않습니다."}};
const ids=new Set(catalog.items.map(r=>r.id));
const results={};
for(const [id, supplement] of Object.entries(additions)){
  if(!ids.has(id))continue;
  const r=catalog.items.find(e=>e.id===id);
  const previous=store.items[id]||{};
  const original=Array.isArray(previous.parts)?previous.parts:(r.sections||[]).map((s,i)=>({heading:s.title||`물음 ${i+1}`,text:s.detailed||''}));
  const parts=[...original,...supplement.parts];
  const chars=parts.map(p=>p.heading+'\n'+p.text).join('\n\n').length;
  store.items[id]={...previous,id,year:r.year,subject:r.subject,points:r.points,title:r.topic,parts,sources:[...(previous.sources||[]),...supplement.sources],caution:supplement.caution,approval:'EXPANDED_STUDY_DRAFT_HOLD',chars};
  results[id]={chars,partsAdded:supplement.parts.length};
}
window.N1091_CONTENT_META={revision:'V10.9.1',expandedCount:Object.keys(results).length,results,independentApproval:false};
})();
